    }

    /**
     * @dev Returns a `BytesSlot` with member `value` located at `slot`.
     */
    function getBytesSlot(bytes32 slot) internal pure returns (BytesSlot storage r) {
        assembly ("memory-safe") {
            r.slot := slot
        }
    }

    /**
     * @dev Returns an `BytesSlot` representation of the bytes storage pointer `store`.
     */
    function getBytesSlot(bytes storage store) internal pure returns (BytesSlot storage r) {
        assembly ("memory-safe") {
            r.slot := store.slot
        }
    }
}

contracts/DripCore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "./interfaces/IDrip.sol";
import "./interfaces/IERC20.sol";
import "./interfaces/IEngagementRewards.sol";
import "./utils/TokenHelper.sol";

/**
 * @title DripCore
 * @notice Main contract for payment streaming functionality with multiple recipients
 * @dev Implements per-second payment streaming with pause/resume/cancel capabilities
 * @dev This contract is upgradeable via proxy pattern
 */
contract DripCore is IDrip, Initializable, ReentrancyGuardUpgradeable, OwnableUpgradeable {
    using TokenHelper for address;

    /// @notice Counter for generating unique stream IDs
    uint256 private _streamIdCounter;

    /// @notice Mapping from stream ID to stream data
    mapping(uint256 => Stream) private _streams;

    /// @notice Mapping from stream ID => recipient => rate per second
    mapping(uint256 => mapping(address => uint256)) private _recipientRates;

    /// @notice Mapping from stream ID => recipient => last withdrawal time
    mapping(uint256 => mapping(address => uint256)) private _recipientLastWithdraw;

    /// @notice Mapping from stream ID => recipient => total withdrawn
    mapping(uint256 => mapping(address => uint256)) private _recipientTotalWithdrawn;

    /// @notice Mapping from sender address to array of stream IDs they created
    mapping(address => uint256[]) private _senderStreams;

    /// @notice Mapping from recipient address to array of stream IDs they receive
    mapping(address => uint256[]) private _recipientStreams;

    /// @notice Mapping to track total paused time for each stream
    mapping(uint256 => uint256) private _pausedTime;

    /// @notice Mapping to track when stream was paused
    mapping(uint256 => uint256) private _pauseStartTime;

    /// @notice Minimum stream duration (1 hour)
    uint256 public constant MIN_DURATION = 3600;

    /// @notice Maximum stream duration (10 years)
    uint256 public constant MAX_DURATION = 315360000;

    /// @notice Maximum title length
    uint256 public constant MAX_TITLE_LEN = 120;

    /// @notice Maximum description length
    uint256 public constant MAX_DESCRIPTION_LEN = 1024;

    /// @notice Platform fee percentage (basis points, e.g., 50 = 0.5%)
    uint256 public platformFeeBps;

    /// @notice Platform fee recipient
    address public platformFeeRecipient;

    /// @notice Engagement Rewards contract address
    IEngagementRewards public engagementRewards;

    /// @notice Whether engagement rewards are enabled
    bool public engagementRewardsEnabled;

    /// @notice Mapping to track if user has claimed reward for first stream creation
    mapping(address => bool) public hasClaimedFirstStreamCreation;

    /// @notice Mapping to track if user has claimed reward for first stream received
    mapping(address => bool) public hasClaimedFirstStreamReceived;

    /// @notice Mapping to track inviter for each user
    mapping(address => address) public userInviter;

    /// @notice Mapping to track if user has claimed reward via direct claimEngagementReward function
    mapping(address => bool) public hasClaimedDirectEngagementReward;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initialize the contract (replaces constructor for upgradeable contracts)
     * @param _platformFeeRecipient Address to receive platform fees
     * @param _owner Address that will own the contract
     */
    function initialize(address _platformFeeRecipient, address _owner) public initializer {
        require(_platformFeeRecipient != address(0), "DripCore: Invalid fee recipient");
        require(_owner != address(0), "DripCore: Invalid owner");

        __ReentrancyGuard_init();
        __Ownable_init(_owner);

        platformFeeRecipient = _platformFeeRecipient;
        platformFeeBps = 50; // 0.5% default - must be set in initializer for upgradeable contracts
        engagementRewardsEnabled = false; // Disabled by default, enable via setter after deployment
    }

    /**
     * @notice Create a new payment stream with multiple recipients
     * @param recipients Array of addresses that will receive the streamed payments
     * @param token ERC20 token address (address(0) for native CELO)
     * @param amountsPerPeriod Array of amounts per period for each recipient
     * @param periodSeconds Duration of the period in seconds
     * @param deposit Total amount to deposit
     * @param title Optional title for the stream
     * @param description Optional description
     * @param inviter Optional inviter address for engagement rewards (can be address(0))
     * @param validUntilBlock Block number until which signature is valid (for engagement rewards)
     * @param signature User signature for engagement rewards (can be empty bytes)
     * @return streamId Unique identifier for the created stream
     */
    function createStream(
        address[] calldata recipients,
        address token,
        uint256[] calldata amountsPerPeriod,
        uint256 periodSeconds,
        uint256 deposit,
        string calldata title,
        string calldata description,
        address inviter,
        uint256 validUntilBlock,
        bytes memory signature
    ) external payable nonReentrant returns (uint256 streamId) {
        return _createStreamInternal(
            recipients,
            token,
            amountsPerPeriod,
            periodSeconds,
            deposit,
            title,
            description,
            inviter,
            validUntilBlock,
            signature
        );
    }

    /**
     * @notice Internal function to create a stream (used by both overloaded functions)
     */
    function _createStreamInternal(
        address[] calldata recipients,
        address token,
        uint256[] calldata amountsPerPeriod,
        uint256 periodSeconds,
        uint256 deposit,
        string calldata title,
        string calldata description,
        address inviter,
        uint256 validUntilBlock,
        bytes memory signature
    ) internal returns (uint256 streamId) {
        require(recipients.length > 0, "DripCore: At least one recipient required");
        require(recipients.length == amountsPerPeriod.length, "DripCore: Mismatched arrays");
        require(deposit > 0, "DripCore: Invalid deposit");
        require(periodSeconds >= MIN_DURATION, "DripCore: Period too short");
        require(periodSeconds <= MAX_DURATION, "DripCore: Period too long");
        require(bytes(title).length <= MAX_TITLE_LEN, "DripCore: Title too long");
        require(bytes(description).length <= MAX_DESCRIPTION_LEN, "DripCore: Description too long");

        // Check for duplicate recipients
        for (uint256 i = 0; i < recipients.length; i++) {
            require(recipients[i] != address(0), "DripCore: Invalid recipient");
            require(recipients[i] != msg.sender, "DripCore: Cannot stream to self");
            require(amountsPerPeriod[i] > 0, "DripCore: Invalid amount");
            for (uint256 j = i + 1; j < recipients.length; j++) {
                require(recipients[i] != recipients[j], "DripCore: Duplicate recipient");
            }
        }

        // Calculate platform fee
        uint256 fee = (deposit * platformFeeBps) / 10000;
        uint256 streamDeposit = deposit - fee;

        // Handle payment
        if (token == TokenHelper.NATIVE_TOKEN) {
            require(msg.value == deposit, "DripCore: Incorrect native amount");
            // Transfer fee to platform
            if (fee > 0) {
                (bool success, ) = platformFeeRecipient.call{value: fee}("");
                require(success, "DripCore: Fee transfer failed");
            }
        } else {
            require(msg.value == 0, "DripCore: Native token not expected");
            // Transfer tokens from sender
            require(
                TokenHelper.safeTransferFrom(token, msg.sender, address(this), streamDeposit),
                "DripCore: Token transfer failed"
            );
            // Transfer fee to platform
            if (fee > 0) {
                require(
                    TokenHelper.safeTransferFrom(token, msg.sender, platformFeeRecipient, fee),
                    "DripCore: Fee transfer failed"
                );
            }
        }

        // Create stream
        streamId = ++_streamIdCounter;
        uint256 startTime = block.timestamp;
        uint256 endTime = startTime + periodSeconds;

        // Store recipients array
        uint256 recipientsLength = recipients.length;
        address[] memory recipientsArray = new address[](recipientsLength);
        for (uint256 i = 0; i < recipientsLength; i++) {
            recipientsArray[i] = recipients[i];
            // Calculate and store rate per second for each recipient
            uint256 ratePerSecond = amountsPerPeriod[i] / periodSeconds;
            require(ratePerSecond > 0, "DripCore: Rate too small");
            _recipientRates[streamId][recipients[i]] = ratePerSecond;
            // Initialize last withdraw time to start time
            _recipientLastWithdraw[streamId][recipients[i]] = startTime;
            // Initialize total withdrawn to 0
            _recipientTotalWithdrawn[streamId][recipients[i]] = 0;
        }

        _streams[streamId] = Stream({
            streamId: streamId,
            sender: msg.sender,
            recipients: recipientsArray,
            token: token,
            deposit: streamDeposit,
            startTime: startTime,
            endTime: endTime,
            status: StreamStatus.Active,
            rateLockUntil: 0,
            title: title,
            description: description
        });

        // Update mappings
        _senderStreams[msg.sender].push(streamId);
        for (uint256 i = 0; i < recipients.length; i++) {
            _recipientStreams[recipients[i]].push(streamId);
        }

        emit StreamCreated(streamId, msg.sender, recipientsArray, token, streamDeposit, startTime, endTime, title, description);

        // Try to claim engagement reward on every stream creation (non-blocking)
        if (engagementRewardsEnabled && address(engagementRewards) != address(0)) {
            address inviterAddress = inviter != address(0) ? inviter : userInviter[msg.sender];
            _tryClaimEngagementReward(
                msg.sender,
                inviterAddress,
                validUntilBlock,
                signature
            );
        }

        return streamId;
    }

    /**
     * @notice Create a new payment stream with multiple recipients (backward compatible overload)
     * @param recipients Array of addresses that will receive the streamed payments
     * @param token ERC20 token address (address(0) for native CELO)
     * @param amountsPerPeriod Array of amounts per period for each recipient
     * @param periodSeconds Duration of the period in seconds
     * @param deposit Total amount to deposit
     * @param title Optional title for the stream
     * @param description Optional description
     * @return streamId Unique identifier for the created stream
     */
    function createStream(
        address[] calldata recipients,
        address token,
        uint256[] calldata amountsPerPeriod,
        uint256 periodSeconds,
        uint256 deposit,
        string calldata title,
        string calldata description
    ) external payable nonReentrant returns (uint256 streamId) {
        return _createStreamInternal(
            recipients,
            token,
            amountsPerPeriod,
            periodSeconds,
            deposit,
            title,
            description,
            address(0), // inviter
            0, // validUntilBlock
            "" // signature
        );
    }

    /**
     * @notice Internal function to calculate recipient balance (used internally to avoid external calls)
     * @param stream The stream data
     * @param streamId The stream identifier
     * @param recipient The recipient address
     * @return balance The amount available for withdrawal
     */
    function _getRecipientBalanceInternal(
        Stream memory stream,
        uint256 streamId,
        address recipient
    ) internal view returns (uint256 balance) {
        // Allow balance calculation for Active, Paused, and Completed streams
        // Completed streams may still have unwithdrawn funds that recipients should be able to claim
        if (stream.status != StreamStatus.Active && stream.status != StreamStatus.Paused && stream.status != StreamStatus.Completed) {
            return 0;
        }

        uint256 ratePerSecond = _recipientRates[streamId][recipient];
        if (ratePerSecond == 0) {
            return 0;
        }

        uint256 currentTime = block.timestamp;
        uint256 lastWithdraw = _recipientLastWithdraw[streamId][recipient];
        if (lastWithdraw == 0) {
            lastWithdraw = stream.startTime;
        }

        // Cap elapsed time at stream endTime
        uint256 effectiveEndTime = currentTime > stream.endTime ? stream.endTime : currentTime;

        // Calculate total paused time (capped at endTime)
        uint256 totalPausedTime = _pausedTime[streamId];
        if (stream.status == StreamStatus.Paused && _pauseStartTime[streamId] > 0) {
            uint256 pauseEnd = effectiveEndTime < _pauseStartTime[streamId] 
                ? _pauseStartTime[streamId] 
                : effectiveEndTime;
            totalPausedTime += (pauseEnd - _pauseStartTime[streamId]);
        }

        // Calculate elapsed time (excluding paused time, capped at endTime)
        uint256 elapsedTime;

        if (effectiveEndTime > lastWithdraw) {
            uint256 rawElapsed = effectiveEndTime - lastWithdraw;
            // Adjust for paused time if pause occurred after last withdraw
            if (_pauseStartTime[streamId] > lastWithdraw && stream.status == StreamStatus.Paused) {
                // Calculate pause duration up to effective end time
                uint256 pauseEndTime = _pauseStartTime[streamId] < effectiveEndTime 
                    ? effectiveEndTime 
                    : _pauseStartTime[streamId];
                uint256 pauseDuration = pauseEndTime - _pauseStartTime[streamId];
                if (rawElapsed > pauseDuration) {
                    elapsedTime = rawElapsed - pauseDuration;
                } else {
                    elapsedTime = 0;
                }
            } else {
                elapsedTime = rawElapsed;
            }
        } else {
            elapsedTime = 0;
        }

        uint256 recipientAccrued = ratePerSecond * elapsedTime;

        // Calculate remaining deposit
        // For expired streams, use actual withdrawals instead of theoretical distribution
        // This ensures recipients can withdraw their unclaimed funds even after stream ends
        uint256 remainingDeposit;
        if (currentTime > stream.endTime) {
            // Stream has expired - calculate based on actual withdrawals, not theoretical distribution
            uint256 totalActualWithdrawn = 0;
            for (uint256 i = 0; i < stream.recipients.length; i++) {
                totalActualWithdrawn += _recipientTotalWithdrawn[streamId][stream.recipients[i]];
            }
            remainingDeposit = stream.deposit > totalActualWithdrawn ? stream.deposit - totalActualWithdrawn : 0;
        } else {
            // Stream not expired - use theoretical distribution
            uint256 totalDistributed = _calculateTotalDistributed(streamId, currentTime);
            remainingDeposit = stream.deposit > totalDistributed ? stream.deposit - totalDistributed : 0;
        }

        // If stream has expired, distribute remaining deposit proportionally among recipients
        if (currentTime > stream.endTime && remainingDeposit > 0) {
            // Calculate total rate for all recipients
            uint256 totalRate = 0;
            for (uint256 i = 0; i < stream.recipients.length; i++) {
                totalRate += _recipientRates[streamId][stream.recipients[i]];
            }

            if (totalRate > 0) {
                // Calculate what this recipient has already withdrawn
                uint256 alreadyWithdrawn = _recipientTotalWithdrawn[streamId][recipient];

                // Calculate what this recipient should have received by endTime (their full allocation)
                uint256 periodSeconds = stream.endTime > stream.startTime ? stream.endTime - stream.startTime : 0;
                uint256 totalPausedTimeForPeriod = _pausedTime[streamId];

                // If stream is currently paused when it expires, add current pause duration
                if (stream.status == StreamStatus.Paused && _pauseStartTime[streamId] > 0) {
                    // Calculate pause duration from pause start to endTime (stream has expired)
                    uint256 pauseEnd = stream.endTime < _pauseStartTime[streamId] 
                        ? _pauseStartTime[streamId] 
                        : stream.endTime;
                    if (pauseEnd > _pauseStartTime[streamId]) {
                        totalPausedTimeForPeriod += (pauseEnd - _pauseStartTime[streamId]);
                    }
                }

                if (periodSeconds > totalPausedTimeForPeriod) {
                    periodSeconds -= totalPausedTimeForPeriod;
                } else {
                    periodSeconds = 0;
                }
                uint256 recipientTotalAllocation = ratePerSecond * periodSeconds;

                // Cap by deposit (in case rates exceed deposit)
                if (recipientTotalAllocation > stream.deposit) {
                    recipientTotalAllocation = stream.deposit;
                }

                // Calculate what recipient should still receive based on their allocation
                uint256 recipientShouldReceive = recipientTotalAllocation > alreadyWithdrawn 
                    ? recipientTotalAllocation - alreadyWithdrawn 
                    : 0;

                // Distribute remaining deposit proportionally
                uint256 recipientProportionalShare = (remainingDeposit * ratePerSecond) / totalRate;

                // Recipient can withdraw: their remaining allocation OR their proportional share of remaining deposit, whichever is larger
                // This ensures they get at least their fair share
                balance = recipientShouldReceive > recipientProportionalShare 
                    ? recipientShouldReceive 
                    : recipientProportionalShare;

                // Cap by remaining deposit
                if (balance > remainingDeposit) {
                    balance = remainingDeposit;
                }
            } else {
                // No rates, use normal calculation capped by remaining deposit
                if (recipientAccrued > remainingDeposit) {
                    recipientAccrued = remainingDeposit;
                }
                balance = recipientAccrued;
            }
        } else {
            // Stream not expired, use normal calculation
            // Cap by remaining deposit
            if (recipientAccrued > remainingDeposit) {
                recipientAccrued = remainingDeposit;
            }
            balance = recipientAccrued;
        }

        return balance;
    }

    /**
     * @notice Get the current balance available for withdrawal for a specific recipient
     * @param streamId The stream identifier
     * @param recipient The recipient address
     * @return balance The amount available for withdrawal
     */
    function getRecipientBalance(uint256 streamId, address recipient) external view returns (uint256 balance) {
        Stream memory stream = _streams[streamId];
        require(stream.streamId != 0, "DripCore: Stream does not exist");
        require(_isRecipient(stream, recipient), "DripCore: Not a recipient");
        return _getRecipientBalanceInternal(stream, streamId, recipient);
    }

    /**
     * @notice Withdraw all available balance from a stream (for a specific recipient)
     * @param streamId The stream identifier
     * @param recipient The recipient address withdrawing
     * @param inviter Optional inviter address for engagement rewards (can be address(0))
     * @param validUntilBlock Block number until which signature is valid (for engagement rewards)
     * @param signature User signature for engagement rewards (can be empty bytes)
     * @return withdrawn The amount actually withdrawn
     */
    function withdrawFromStream(
        uint256 streamId,
        address recipient,
        address inviter,
        uint256 validUntilBlock,
        bytes memory signature
    ) external nonReentrant returns (uint256 withdrawn) {
        return _withdrawFromStreamInternal(
            streamId,
            recipient,
            inviter,
            validUntilBlock,
            signature
        );
    }

    /**
     * @notice Internal function to withdraw from stream (used by both overloaded functions)
     */
    function _withdrawFromStreamInternal(
        uint256 streamId,
        address recipient,
        address inviter,
        uint256 validUntilBlock,
        bytes memory signature
    ) internal returns (uint256 withdrawn) {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCore: Stream does not exist");
        require(
            stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused || stream.status == StreamStatus.Completed,
            "DripCore: Stream not active, paused, or completed"
        );
        require(_isRecipient(stream, recipient), "DripCore: Not a recipient");
        require(msg.sender == recipient, "DripCore: Only recipient can withdraw");

        uint256 availableBalance = _getRecipientBalanceInternal(stream, streamId, recipient);
        require(availableBalance > 0, "DripCore: No balance available");

        // Always withdraw the full available balance
            withdrawn = availableBalance;

        // Update recipient tracking
        _recipientTotalWithdrawn[streamId][recipient] += withdrawn;
        _recipientLastWithdraw[streamId][recipient] = block.timestamp;

        // Transfer funds (dynamic token support - native CELO or ERC20)
        // TokenHelper.safeTransfer handles both token types automatically
        require(
            TokenHelper.safeTransfer(stream.token, recipient, withdrawn),
            "DripCore: Transfer failed"
        );

        // Check if stream deposit is exhausted
        uint256 totalDistributed = _calculateTotalDistributed(streamId, block.timestamp);
        if (totalDistributed >= stream.deposit) {
            stream.status = StreamStatus.Completed;
            emit StreamCompleted(streamId);
        }

        emit StreamWithdrawn(streamId, recipient, withdrawn);

        // Try to claim engagement reward on every withdrawal (non-blocking)
        if (engagementRewardsEnabled && address(engagementRewards) != address(0)) {
            address inviterAddress = inviter != address(0) ? inviter : userInviter[recipient];
            _tryClaimEngagementReward(
                recipient,
                inviterAddress,
                validUntilBlock,
                signature
            );
        }

        return withdrawn;
    }

    /**
     * @notice Withdraw all available balance from a stream (backward compatible overload)
     * @param streamId The stream identifier
     * @param recipient The recipient address withdrawing
     * @return withdrawn The amount actually withdrawn
     */
    function withdrawFromStream(
        uint256 streamId,
        address recipient
    ) external nonReentrant returns (uint256 withdrawn) {
        return _withdrawFromStreamInternal(
            streamId,
            recipient,
            address(0), // inviter
            0, // validUntilBlock
            "" // signature
        );
    }

    /**
     * @notice Claim engagement rewards directly without stream operations
     * @dev Allows users to claim GoodDollar rewards independently
     * @dev On first claim: requires valid signature and validUntilBlock > current block
     * @dev On subsequent claims: can pass empty signature and validUntilBlock = 0
     * @param inviter Optional inviter address (can be address(0))
     * @param validUntilBlock Block number until which signature is valid (required on first claim, can be 0 after)
     * @param signature User signature for verification (required on first claim, can be empty after)
     * @return success Whether the claim was successful
     */
    function claimEngagementReward(
        address inviter,
        uint256 validUntilBlock,
        bytes memory signature
    ) external nonReentrant returns (bool success) {
        require(engagementRewardsEnabled, "DripCore: Engagement rewards disabled");
        require(address(engagementRewards) != address(0), "DripCore: No rewards contract");

        // On first claim: require valid signature and block
        // On subsequent claims: can pass empty signature and block 0
        if (!hasClaimedDirectEngagementReward[msg.sender]) {
            require(validUntilBlock > block.number, "DripCore: Signature expired (first claim requires valid block)");
            require(signature.length > 0, "DripCore: Signature required on first claim");
        }

        // Determine inviter address
        address inviterAddress = inviter != address(0) ? inviter : userInviter[msg.sender];

        // Attempt to claim reward
        try engagementRewards.appClaim(
            msg.sender,
            inviterAddress,
            validUntilBlock,
            signature
        ) returns (bool claimSuccess) {
            emit EngagementRewardClaimed(msg.sender, inviterAddress, claimSuccess);

            // Mark as claimed after first attempt (whether successful or not)
            if (!hasClaimedDirectEngagementReward[msg.sender]) {
                hasClaimedDirectEngagementReward[msg.sender] = true;
            }

            return claimSuccess;
        } catch Error(string memory reason) {
            emit EngagementRewardClaimFailed(msg.sender, reason);

            // Mark as claimed after first attempt (even if failed)
            if (!hasClaimedDirectEngagementReward[msg.sender]) {
                hasClaimedDirectEngagementReward[msg.sender] = true;
            }

            return false;
        } catch {
            emit EngagementRewardClaimFailed(msg.sender, "Unknown error");

            // Mark as claimed after first attempt (even if failed)
            if (!hasClaimedDirectEngagementReward[msg.sender]) {
                hasClaimedDirectEngagementReward[msg.sender] = true;
            }

            return false;
        }
    }

    /**
     * @notice Get detailed information about a specific recipient in a stream
     * @param streamId The stream identifier
     * @param recipient The recipient address
     * @return info Recipient information structure
     */
    function getRecipientInfo(uint256 streamId, address recipient) external view returns (RecipientInfo memory info) {
        Stream memory stream = _streams[streamId];
        require(stream.streamId != 0, "DripCore: Stream does not exist");
        require(_isRecipient(stream, recipient), "DripCore: Not a recipient");

        uint256 lastWithdraw = _recipientLastWithdraw[streamId][recipient];
        if (lastWithdraw == 0) {
            lastWithdraw = stream.startTime;
        }

        info = RecipientInfo({
            recipient: recipient,
            ratePerSecond: _recipientRates[streamId][recipient],
            totalWithdrawn: _recipientTotalWithdrawn[streamId][recipient],
            lastWithdrawTime: lastWithdraw,
            currentAccrued: _getRecipientBalanceInternal(_streams[streamId], streamId, recipient)
        });

        return info;
    }

    /**
     * @notice Get information about all recipients in a stream
     * @param streamId The stream identifier
     * @return recipients Array of recipient information
     */
    function getAllRecipientsInfo(uint256 streamId) external view returns (RecipientInfo[] memory recipients) {
        Stream memory stream = _streams[streamId];
        require(stream.streamId != 0, "DripCore: Stream does not exist");

        recipients = new RecipientInfo[](stream.recipients.length);
        for (uint256 i = 0; i < stream.recipients.length; i++) {
            recipients[i] = this.getRecipientInfo(streamId, stream.recipients[i]);
        }

        return recipients;
    }

    /**
     * @notice Pause an active stream
     * @param streamId The stream identifier
     */
    function pauseStream(uint256 streamId) external {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCore: Stream does not exist");
        require(stream.status == StreamStatus.Active, "DripCore: Stream not active");
        require(
            msg.sender == stream.sender || msg.sender == owner(),
            "DripCore: Unauthorized"
        );

        _pauseStartTime[streamId] = block.timestamp;
        stream.status = StreamStatus.Paused;
        emit StreamPaused(streamId, msg.sender);
    }

    /**
     * @notice Resume a paused stream
     * @param streamId The stream identifier
     */
    function resumeStream(uint256 streamId) external {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCore: Stream does not exist");
        require(stream.status == StreamStatus.Paused, "DripCore: Stream not paused");
        require(
            msg.sender == stream.sender || msg.sender == owner(),
            "DripCore: Unauthorized"
        );

        if (_pauseStartTime[streamId] > 0) {
            _pausedTime[streamId] += (block.timestamp - _pauseStartTime[streamId]);
            _pauseStartTime[streamId] = 0;
        }

        stream.status = StreamStatus.Active;
        emit StreamResumed(streamId, msg.sender);
    }

    /**
     * @notice Cancel a stream and refund remaining balance
     * @param streamId The stream identifier
     */
    function cancelStream(uint256 streamId) external nonReentrant {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCore: Stream does not exist");
        require(
            stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused,
            "DripCore: Stream cannot be cancelled"
        );
        require(
            msg.sender == stream.sender || msg.sender == owner(),
            "DripCore: Unauthorized"
        );

        // Ensure recipients receive all accrued funds before refunding sender
        _settleAllRecipients(stream, streamId);

        // Calculate remaining deposit
        uint256 totalDistributed = _calculateTotalDistributed(streamId, block.timestamp);
        uint256 refundAmount = stream.deposit > totalDistributed ? stream.deposit - totalDistributed : 0;

        stream.status = StreamStatus.Cancelled;
        stream.deposit = 0;

        // Refund remaining balance to sender (dynamic token support)
        // TokenHelper.safeTransfer handles both native CELO and ERC20 tokens
        if (refundAmount > 0) {
            // Verify contract has sufficient balance
            if (stream.token == TokenHelper.NATIVE_TOKEN) {
                require(address(this).balance >= refundAmount, "DripCore: Insufficient contract balance");
            } else {
                uint256 contractBalance = TokenHelper.getBalance(stream.token, address(this));
                require(contractBalance >= refundAmount, "DripCore: Insufficient contract balance");
            }

            require(
                TokenHelper.safeTransfer(stream.token, stream.sender, refundAmount),
                "DripCore: Refund failed"
            );
        }

        emit StreamCancelled(streamId, msg.sender, refundAmount);
    }

    /**
     * @notice Lock rate-related modifications for a stream
     */
    function lockStreamRate(uint256 streamId, uint256 lockDuration) external {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCore: Stream does not exist");
        require(
            stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused,
            "DripCore: Stream not active"
        );
        require(msg.sender == stream.sender, "DripCore: Only sender can lock");
        require(lockDuration > 0, "DripCore: Invalid duration");

        uint256 lockUntil = block.timestamp + lockDuration;
        require(lockUntil > block.timestamp, "DripCore: Duration overflow");
        require(lockUntil > stream.rateLockUntil, "DripCore: Lock already active");

        stream.rateLockUntil = lockUntil;
        emit StreamRateLocked(streamId, lockUntil);
    }

    /**
     * @notice Extend a stream's duration or add extra deposit
     */
    function extendStream(
        uint256 streamId,
        uint256 newEndTime,
        uint256 depositAmount
    ) external payable nonReentrant {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCore: Stream does not exist");
        require(
            stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused,
            "DripCore: Stream not active"
        );
        require(msg.sender == stream.sender, "DripCore: Only sender can extend");
        _requireRateUnlocked(stream);
        require(newEndTime == 0 || newEndTime >= stream.endTime, "DripCore: Invalid end time");
        require(depositAmount > 0 || newEndTime > stream.endTime, "DripCore: Nothing to update");

        uint256 requiredDeposit = 0;
        if (newEndTime > stream.endTime) {
            address[] storage recipients = stream.recipients;
            require(recipients.length > 0, "DripCore: No recipients");
            uint256 totalRate = _getTotalStreamRate(streamId, recipients);
            require(totalRate > 0, "DripCore: Total rate is zero");
            requiredDeposit = totalRate * (newEndTime - stream.endTime);
        }

        uint256 netDepositAdded = 0;
        if (depositAmount > 0) {
            uint256 fee = (depositAmount * platformFeeBps) / 10000;
            netDepositAdded = depositAmount - fee;
            require(netDepositAdded > 0, "DripCore: Deposit too small");

            if (stream.token == TokenHelper.NATIVE_TOKEN) {
                require(msg.value == depositAmount, "DripCore: Incorrect native amount");
                if (fee > 0) {
                    (bool success, ) = platformFeeRecipient.call{value: fee}("");
                    require(success, "DripCore: Fee transfer failed");
                }
            } else {
                require(msg.value == 0, "DripCore: Native token not expected");
                require(
                    TokenHelper.safeTransferFrom(stream.token, msg.sender, address(this), netDepositAdded),
                    "DripCore: Token transfer failed"
                );
                if (fee > 0) {
                    require(
                        TokenHelper.safeTransferFrom(stream.token, msg.sender, platformFeeRecipient, fee),
                        "DripCore: Fee transfer failed"
                    );
                }
            }

            stream.deposit += netDepositAdded;
        } else {
            require(msg.value == 0, "DripCore: Native token not expected");
        }

        if (requiredDeposit > 0) {
            require(netDepositAdded >= requiredDeposit, "DripCore: Insufficient deposit for extension");
            stream.endTime = newEndTime;
        } else if (newEndTime > stream.endTime) {
            // In practice requiredDeposit will be > 0 when newEndTime increases, but keep guard
            stream.endTime = newEndTime;
        }

        emit StreamExtended(streamId, stream.endTime, netDepositAdded);
    }

    /**
     * @notice Add a new recipient to an existing stream
     * @param streamId The stream identifier
     * @param recipient The new recipient address
     * @param amountPerPeriod The amount per period for the new recipient
     * @param additionalDeposit Additional deposit required to cover the new recipient
     */
    function addRecipient(
        uint256 streamId,
        address recipient,
        uint256 amountPerPeriod,
        uint256 additionalDeposit
    ) external payable nonReentrant {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCore: Stream does not exist");
        require(
            stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused,
            "DripCore: Stream not active or paused"
        );
        _requireRateUnlocked(stream);
        require(msg.sender == stream.sender, "DripCore: Only sender can modify recipients");
        require(recipient != address(0), "DripCore: Invalid recipient");
        require(recipient != msg.sender, "DripCore: Cannot stream to self");
        require(amountPerPeriod > 0, "DripCore: Invalid amount");
        require(!_isRecipient(stream, recipient), "DripCore: Recipient already exists");

        // Calculate rate per second
        uint256 periodSeconds = stream.endTime - stream.startTime;
        uint256 ratePerSecond = amountPerPeriod / periodSeconds;
        require(ratePerSecond > 0, "DripCore: Rate too small");

        // Calculate required additional deposit
        uint256 requiredDeposit = additionalDeposit;
        if (requiredDeposit > 0) {
            // Calculate platform fee
            uint256 fee = (requiredDeposit * platformFeeBps) / 10000;
            uint256 netDeposit = requiredDeposit - fee;

            // Handle payment
            if (stream.token == TokenHelper.NATIVE_TOKEN) {
                require(msg.value == requiredDeposit, "DripCore: Incorrect native amount");
                // Transfer fee to platform
                if (fee > 0) {
                    (bool success, ) = platformFeeRecipient.call{value: fee}("");
                    require(success, "DripCore: Fee transfer failed");
                }
            } else {
                require(msg.value == 0, "DripCore: Native token not expected");
                // Transfer tokens from sender
                require(
                    TokenHelper.safeTransferFrom(stream.token, msg.sender, address(this), netDeposit),
                    "DripCore: Token transfer failed"
                );
                // Transfer fee to platform
                if (fee > 0) {
                    require(
                        TokenHelper.safeTransferFrom(stream.token, msg.sender, platformFeeRecipient, fee),
                        "DripCore: Fee transfer failed"
                    );
                }
            }

            // Update stream deposit
            stream.deposit += netDeposit;
        }

        // Add recipient to array (need to create new array)
        address[] memory newRecipients = new address[](stream.recipients.length + 1);
        for (uint256 i = 0; i < stream.recipients.length; i++) {
            newRecipients[i] = stream.recipients[i];
        }
        newRecipients[stream.recipients.length] = recipient;
        stream.recipients = newRecipients;

        // Store recipient rate and initialize tracking
        _recipientRates[streamId][recipient] = ratePerSecond;
        _recipientLastWithdraw[streamId][recipient] = stream.startTime;
        _recipientTotalWithdrawn[streamId][recipient] = 0;

        // Update recipient streams mapping
        _recipientStreams[recipient].push(streamId);

        emit RecipientAdded(streamId, recipient, amountPerPeriod, ratePerSecond);
    }

    /**
     * @notice Remove a recipient from an existing stream
     * @param streamId The stream identifier
     * @param recipient The recipient address to remove
     */
    function removeRecipient(uint256 streamId, address recipient) external nonReentrant {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCore: Stream does not exist");
        require(
            stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused,
            "DripCore: Stream not active or paused"
        );
        _requireRateUnlocked(stream);
        require(msg.sender == stream.sender, "DripCore: Only sender can modify recipients");
        require(_isRecipient(stream, recipient), "DripCore: Recipient does not exist");

        // Calculate unaccrued deposit for this recipient
        uint256 ratePerSecond = _recipientRates[streamId][recipient];
        uint256 currentTime = block.timestamp;
        uint256 elapsedTime = currentTime > stream.startTime ? currentTime - stream.startTime : 0;

        // Account for paused time
        uint256 totalPausedTime = _pausedTime[streamId];
        if (stream.status == StreamStatus.Paused && _pauseStartTime[streamId] > 0) {
            totalPausedTime += (currentTime - _pauseStartTime[streamId]);
        }
        if (elapsedTime > totalPausedTime) {
            elapsedTime -= totalPausedTime;
        } else {
            elapsedTime = 0;
        }

        uint256 totalAccrued = ratePerSecond * elapsedTime;
        uint256 periodSeconds = stream.endTime - stream.startTime;
        uint256 totalAllocated = (ratePerSecond * periodSeconds);
        uint256 unaccruedDeposit = totalAllocated > totalAccrued ? totalAllocated - totalAccrued : 0;

        // Refund unaccrued deposit to sender
        if (unaccruedDeposit > 0 && stream.deposit >= unaccruedDeposit) {
            stream.deposit -= unaccruedDeposit;
            require(
                TokenHelper.safeTransfer(stream.token, stream.sender, unaccruedDeposit),
                "DripCore: Refund failed"
            );
        }

        // Remove recipient from array
        address[] memory newRecipients = new address[](stream.recipients.length - 1);
        uint256 newIndex = 0;
        for (uint256 i = 0; i < stream.recipients.length; i++) {
            if (stream.recipients[i] != recipient) {
                newRecipients[newIndex] = stream.recipients[i];
                newIndex++;
            }
        }
        stream.recipients = newRecipients;

        // Clear recipient data
        delete _recipientRates[streamId][recipient];
        delete _recipientLastWithdraw[streamId][recipient];
        delete _recipientTotalWithdrawn[streamId][recipient];

        // Remove from recipient streams mapping (find and remove)
        uint256[] storage recipientStreams = _recipientStreams[recipient];
        for (uint256 i = 0; i < recipientStreams.length; i++) {
            if (recipientStreams[i] == streamId) {
                recipientStreams[i] = recipientStreams[recipientStreams.length - 1];
                recipientStreams.pop();
                break;
            }
        }

        emit RecipientRemoved(streamId, recipient, unaccruedDeposit);
    }

    /**
     * @notice Update a recipient's rate in an existing stream
     * @param streamId The stream identifier
     * @param recipient The recipient address
     * @param newAmountPerPeriod The new amount per period
     * @param additionalDeposit Additional deposit if increasing rate (0 if decreasing)
     */
    function updateRecipientRate(
        uint256 streamId,
        address recipient,
        uint256 newAmountPerPeriod,
        uint256 additionalDeposit
    ) external payable nonReentrant {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCore: Stream does not exist");
        require(
            stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused,
            "DripCore: Stream not active or paused"
        );
        _requireRateUnlocked(stream);
        require(msg.sender == stream.sender, "DripCore: Only sender can modify recipients");
        require(_isRecipient(stream, recipient), "DripCore: Recipient does not exist");
        require(newAmountPerPeriod > 0, "DripCore: Invalid amount");

        uint256 oldRatePerSecond = _recipientRates[streamId][recipient];
        uint256 periodSeconds = stream.endTime - stream.startTime;
        uint256 newRatePerSecond = newAmountPerPeriod / periodSeconds;
        require(newRatePerSecond > 0, "DripCore: Rate too small");

        // Calculate difference in total allocation
        uint256 oldTotalAllocation = oldRatePerSecond * periodSeconds;
        uint256 newTotalAllocation = newRatePerSecond * periodSeconds;

        if (newTotalAllocation > oldTotalAllocation) {
            // Rate increased - need additional deposit
            uint256 requiredDeposit = newTotalAllocation - oldTotalAllocation;
            require(additionalDeposit >= requiredDeposit, "DripCore: Insufficient additional deposit");

            if (requiredDeposit > 0) {
                // Calculate platform fee
                uint256 fee = (requiredDeposit * platformFeeBps) / 10000;
                uint256 netDeposit = requiredDeposit - fee;

                // Handle payment
                if (stream.token == TokenHelper.NATIVE_TOKEN) {
                    require(msg.value == requiredDeposit, "DripCore: Incorrect native amount");
                    // Transfer fee to platform
                    if (fee > 0) {
                        (bool success, ) = platformFeeRecipient.call{value: fee}("");
                        require(success, "DripCore: Fee transfer failed");
                    }
                } else {
                    require(msg.value == 0, "DripCore: Native token not expected");
                    // Transfer tokens from sender
                    require(
                        TokenHelper.safeTransferFrom(stream.token, msg.sender, address(this), netDeposit),
                        "DripCore: Token transfer failed"
                    );
                    // Transfer fee to platform
                    if (fee > 0) {
                        require(
                            TokenHelper.safeTransferFrom(stream.token, msg.sender, platformFeeRecipient, fee),
                            "DripCore: Fee transfer failed"
                        );
                    }
                }

                stream.deposit += netDeposit;
            }
        } else {
            // Rate decreased - refund difference
            uint256 refundAmount = oldTotalAllocation - newTotalAllocation;
            if (refundAmount > 0 && stream.deposit >= refundAmount) {
                stream.deposit -= refundAmount;
                require(
                    TokenHelper.safeTransfer(stream.token, stream.sender, refundAmount),
                    "DripCore: Refund failed"
                );
            }
        }

        // Update recipient rate
        _recipientRates[streamId][recipient] = newRatePerSecond;

        emit RecipientRateUpdated(streamId, recipient, oldRatePerSecond, newRatePerSecond);
    }

    /**
     * @notice Get stream details
     * @param streamId The stream identifier
     * @return stream The stream structure
     */
    function getStream(uint256 streamId) external view returns (Stream memory stream) {
        stream = _streams[streamId];
        require(stream.streamId != 0, "DripCore: Stream does not exist");
        return stream;
    }

    /**
     * @notice Get all stream IDs for a sender
     * @param sender The sender address
     * @return streamIds Array of stream IDs
     */
    function getSenderStreams(address sender) external view returns (uint256[] memory streamIds) {
        return _senderStreams[sender];
    }

    /**
     * @notice Get all stream IDs for a recipient
     * @param recipient The recipient address
     * @return streamIds Array of stream IDs
     */
    function getRecipientStreams(address recipient) external view returns (uint256[] memory streamIds) {
        return _recipientStreams[recipient];
    }

    /**
     * @notice Get all streams where user is sender
     * @param user The user address
     * @return streams Array of stream structures
     */
    function getUserSentStreams(address user) external view returns (Stream[] memory streams) {
        uint256[] memory streamIds = _senderStreams[user];
        streams = new Stream[](streamIds.length);
        for (uint256 i = 0; i < streamIds.length; i++) {
            streams[i] = _streams[streamIds[i]];
        }
        return streams;
    }

    /**
     * @notice Get all streams where user is recipient
     * @param user The user address
     * @return streams Array of stream structures
     */
    function getUserReceivedStreams(address user) external view returns (Stream[] memory streams) {
        uint256[] memory streamIds = _recipientStreams[user];
        streams = new Stream[](streamIds.length);
        for (uint256 i = 0; i < streamIds.length; i++) {
            streams[i] = _streams[streamIds[i]];
        }
        return streams;
    }

    /**
     * @notice Update platform fee (owner only)
     * @param newFeeBps New fee in basis points
     */
    function setPlatformFee(uint256 newFeeBps) external onlyOwner {
        require(newFeeBps <= 1000, "DripCore: Fee too high"); // Max 10%
        platformFeeBps = newFeeBps;
    }

    /**
     * @notice Update platform fee recipient (owner only)
     * @param newRecipient New fee recipient address
     */
    function setPlatformFeeRecipient(address newRecipient) external onlyOwner {
        require(newRecipient != address(0), "DripCore: Invalid recipient");
        platformFeeRecipient = newRecipient;
    }

    /**
     * @notice Set the Engagement Rewards contract address (owner only)
     * @param _engagementRewards Address of the Engagement Rewards contract
     */
    function setEngagementRewards(address _engagementRewards) external onlyOwner {
        require(_engagementRewards != address(0), "DripCore: Invalid address");
        engagementRewards = IEngagementRewards(_engagementRewards);
        emit EngagementRewardsContractSet(_engagementRewards);
    }

    /**
     * @notice Enable or disable engagement rewards (owner only)
     * @param _enabled Whether to enable engagement rewards
     */
    function setEngagementRewardsEnabled(bool _enabled) external onlyOwner {
        engagementRewardsEnabled = _enabled;
        emit EngagementRewardsEnabledSet(_enabled);
    }

    /**
     * @notice Set inviter address for the caller
     * @param inviter Address of the inviter
     */
    function setInviter(address inviter) external {
        require(inviter != address(0), "DripCore: Invalid inviter");
        require(inviter != msg.sender, "DripCore: Cannot invite self");
        require(userInviter[msg.sender] == address(0), "DripCore: Inviter already set");
        userInviter[msg.sender] = inviter;
        emit InviterSet(msg.sender, inviter);
    }

    /**
     * @notice Internal function to attempt engagement reward claim (non-blocking)
     * @param user Address of the user claiming the reward
     * @param inviter Address of the inviter (can be address(0))
     * @param validUntilBlock Block number until which signature is valid
     * @param signature User signature (can be empty bytes for subsequent claims)
     */
    function _tryClaimEngagementReward(
        address user,
        address inviter,
        uint256 validUntilBlock,
        bytes memory signature
    ) internal {
        if (address(engagementRewards) == address(0)) return;
        if (!engagementRewardsEnabled) return;

        // If validUntilBlock is 0, skip claiming (frontend didn't provide it)
        if (validUntilBlock == 0) return;

        // If validUntilBlock is in the past, skip claiming
        if (validUntilBlock < block.number) return;

        try engagementRewards.appClaim(
            user,
            inviter,
            validUntilBlock,
            signature
        ) returns (bool success) {
            if (success) {
                emit EngagementRewardClaimed(user, inviter, true);
            } else {
                emit EngagementRewardClaimed(user, inviter, false);
            }
        } catch Error(string memory reason) {
            emit EngagementRewardClaimFailed(user, reason);
        } catch {
            emit EngagementRewardClaimFailed(user, "Unknown error");
        }
    }

    /**
     * @notice Get the contract's total balance for a specific token
     * @dev Useful for checking contract's total escrow for a token type
     * @param token Token address (address(0) for native CELO)
     * @return balance The contract's balance for the token
     */
    function getContractBalance(address token) external view returns (uint256 balance) {
        return TokenHelper.getBalance(token, address(this));
    }

    /**
     * @notice Internal helper to enforce rate lock rules
     */
    function _requireRateUnlocked(Stream storage stream) internal view {
        require(
            stream.rateLockUntil == 0 || block.timestamp >= stream.rateLockUntil,
            "DripCore: Stream rate locked"
        );
    }

    /**
     * @notice Internal function to settle accrued funds for a recipient
     */
    function _settleRecipientAccrued(
        Stream storage stream,
        uint256 streamId,
        address recipient
    ) internal returns (uint256) {
        uint256 availableBalance = _getRecipientBalanceInternal(stream, streamId, recipient);
        if (availableBalance == 0) {
            return 0;
        }

        _recipientTotalWithdrawn[streamId][recipient] += availableBalance;
        _recipientLastWithdraw[streamId][recipient] = block.timestamp;

        require(
            TokenHelper.safeTransfer(stream.token, recipient, availableBalance),
            "DripCore: Transfer failed"
        );

        emit StreamWithdrawn(streamId, recipient, availableBalance);
        return availableBalance;
    }

    /**
     * @notice Internal function to settle all recipients before cancellation
     */
    function _settleAllRecipients(Stream storage stream, uint256 streamId) internal {
        address[] storage recipients = stream.recipients;
        for (uint256 i = 0; i < recipients.length; i++) {
            _settleRecipientAccrued(stream, streamId, recipients[i]);
        }
    }

    /**
     * @notice Helper to compute total stream outflow rate
     */
    function _getTotalStreamRate(
        uint256 streamId,
        address[] storage recipients
    ) internal view returns (uint256 totalRate) {
        for (uint256 i = 0; i < recipients.length; i++) {
            totalRate += _recipientRates[streamId][recipients[i]];
        }
    }

    /**
     * @notice Internal function to check if address is a recipient
     */
    function _isRecipient(Stream memory stream, address recipient) internal pure returns (bool) {
        for (uint256 i = 0; i < stream.recipients.length; i++) {
            if (stream.recipients[i] == recipient) {
                return true;
            }
        }
        return false;
    }

    /**
     * @notice Internal function to calculate total distributed across all recipients
     */
    function _calculateTotalDistributed(uint256 streamId, uint256 currentTime) internal view returns (uint256) {
        Stream memory stream = _streams[streamId];
        if (stream.streamId == 0) return 0;

        uint256 totalOutflowRate = 0;
        for (uint256 i = 0; i < stream.recipients.length; i++) {
            totalOutflowRate += _recipientRates[streamId][stream.recipients[i]];
        }

        // Cap elapsed time at stream endTime
        uint256 effectiveEndTime = currentTime > stream.endTime ? stream.endTime : currentTime;

        // Calculate total paused time (capped at endTime)
        uint256 totalPausedTime = _pausedTime[streamId];
        if (stream.status == StreamStatus.Paused && _pauseStartTime[streamId] > 0) {
            uint256 pauseEnd = effectiveEndTime < _pauseStartTime[streamId] 
                ? _pauseStartTime[streamId] 
                : effectiveEndTime;
            totalPausedTime += (pauseEnd - _pauseStartTime[streamId]);
        }
        uint256 elapsedFromStart = effectiveEndTime > stream.startTime ? effectiveEndTime - stream.startTime : 0;

        if (elapsedFromStart > totalPausedTime) {
            elapsedFromStart -= totalPausedTime;
        } else {
            elapsedFromStart = 0;
        }

        uint256 totalDistributed = totalOutflowRate * elapsedFromStart;

        // Cap by deposit
        if (totalDistributed > stream.deposit) {
            totalDistributed = stream.deposit;
        }

        return totalDistributed;
    }

    /**
     * @notice Emergency withdrawal function - withdraw all native CELO from contract (owner only)
     * @dev This function allows the owner to withdraw all native CELO in case of emergency
     * @param to Address to send the funds to
     */
    function emergencyWithdrawNative(address payable to) external onlyOwner {
        require(to != address(0), "DripCore: Invalid recipient");
        uint256 balance = address(this).balance;
        require(balance > 0, "DripCore: No native balance");

        (bool success, ) = to.call{value: balance}("");
        require(success, "DripCore: Native withdrawal failed");

        emit EmergencyWithdrawal(address(0), to, balance);
    }

    /**
     * @notice Emergency withdrawal function - withdraw specific ERC20 token from contract (owner only)
     * @dev This function allows the owner to withdraw all of a specific ERC20 token in case of emergency
     * @param token Token address to withdraw
     * @param to Address to send the funds to
     */
    function emergencyWithdrawToken(address token, address to) external onlyOwner {
        require(token != address(0), "DripCore: Invalid token address");
        require(to != address(0), "DripCore: Invalid recipient");

        uint256 balance = TokenHelper.getBalance(token, address(this));
        require(balance > 0, "DripCore: No token balance");

        require(
            TokenHelper.safeTransfer(token, to, balance),
            "DripCore: Token withdrawal failed"
        );

        emit EmergencyWithdrawal(token, to, balance);
    }

    /**
     * @notice Emergency withdrawal function - withdraw multiple ERC20 tokens at once (owner only)
     * @dev This function allows the owner to withdraw all of multiple ERC20 tokens in a single transaction
     * @param tokens Array of token addresses to withdraw
     * @param to Address to send the funds to
     */
    function emergencyWithdrawTokens(address[] calldata tokens, address to) external onlyOwner {
        require(to != address(0), "DripCore: Invalid recipient");
        require(tokens.length > 0, "DripCore: Empty tokens array");

        for (uint256 i = 0; i < tokens.length; i++) {
            address token = tokens[i];
            if (token == address(0)) {
                // Skip native token - use emergencyWithdrawNative instead
                continue;
            }

            uint256 balance = TokenHelper.getBalance(token, address(this));
            if (balance > 0) {
                require(
                    TokenHelper.safeTransfer(token, to, balance),
                    "DripCore: Token withdrawal failed"
                );
                emit EmergencyWithdrawal(token, to, balance);
            }
        }
    }

    /**
     * @notice Emergency withdrawal function - withdraw ALL funds from contract (owner only)
     * @dev This function withdraws all native CELO and all specified ERC20 tokens in a single transaction
     * @dev Use this function to completely drain the contract if you want to abandon it
     * @param tokens Array of ERC20 token addresses to withdraw (can be empty if only withdrawing native)
     * @param to Address to send all funds to
     */
    function emergencyWithdrawAll(address[] calldata tokens, address payable to) external onlyOwner {
        require(to != address(0), "DripCore: Invalid recipient");

        // Withdraw all native CELO
        uint256 nativeBalance = address(this).balance;
        if (nativeBalance > 0) {
            (bool success, ) = to.call{value: nativeBalance}("");
            require(success, "DripCore: Native withdrawal failed");
            emit EmergencyWithdrawal(address(0), to, nativeBalance);
        }

        // Withdraw all specified ERC20 tokens
        for (uint256 i = 0; i < tokens.length; i++) {
            address token = tokens[i];
            require(token != address(0), "DripCore: Invalid token address (use address(0) for native)");

            uint256 balance = TokenHelper.getBalance(token, address(this));
            if (balance > 0) {
                require(
                    TokenHelper.safeTransfer(token, to, balance),
                    "DripCore: Token withdrawal failed"
                );
                emit EmergencyWithdrawal(token, to, balance);
            }
        }
    }

    /**
     * @notice Get contract balances for multiple tokens (view function)
     * @dev Helper function to check balances before calling emergencyWithdrawAll
     * @param tokens Array of token addresses to check (use address(0) for native CELO)
     * @return balances Array of balances corresponding to the tokens array
     */
    function getContractBalances(address[] calldata tokens) external view returns (uint256[] memory balances) {
        balances = new uint256[](tokens.length);
        for (uint256 i = 0; i < tokens.length; i++) {
            balances[i] = TokenHelper.getBalance(tokens[i], address(this));
        }
        return balances;
    }

    /**
     * @notice Receive native CELO
     */
    receive() external payable {
        // Allow contract to receive native CELO
    }

    // Engagement Rewards Events
    event EngagementRewardClaimed(address indexed user, address indexed inviter, bool success);
    event EngagementRewardClaimFailed(address indexed user, string reason);
    event EngagementRewardsContractSet(address indexed contractAddress);
    event EngagementRewardsEnabledSet(bool enabled);
    event InviterSet(address indexed user, address indexed inviter);
}

contracts/DripCoreSuperfluid.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "./interfaces/IDrip.sol";

struct PoolConfig {
    bool transferabilityForUnitsOwner;
    bool distributionFromAnyAddress;
}

interface ISuperfluidPool {
    function updateMemberUnits(address memberAddr, uint128 newUnits) external returns (bool);
    function claimAll(address memberAddr) external returns (bool);
    function getClaimableNow(address memberAddr) external view returns (int256 claimableBalance, uint256 timestamp);
}

interface ISuperToken {
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IGDAv1Forwarder {
    function createPool(address token, address admin, PoolConfig memory config) external returns (bool success, ISuperfluidPool pool);
    function distributeFlow(address token, address from, ISuperfluidPool pool, int96 requestedFlowRate, bytes calldata userData) external returns (bool success);
}

contract DripCoreSuperfluid is IDrip, Initializable, ReentrancyGuardUpgradeable, OwnableUpgradeable {
    uint256 public constant MIN_DURATION = 3600;
    uint256 public constant MAX_DURATION = 315360000;
    uint256 public constant MAX_TITLE_LEN = 120;
    uint256 public constant MAX_DESCRIPTION_LEN = 1024;

    struct StreamRuntime {
        ISuperfluidPool pool;
        int96 totalFlowRate;
        uint256 remainingBudget;
        uint256 totalDistributedAccounting;
        uint256 lastAccountingTimestamp;
    }

    uint256 private _streamIdCounter;

    mapping(uint256 => Stream) private _streams;
    mapping(uint256 => StreamRuntime) private _streamRuntime;

    mapping(uint256 => mapping(address => bool)) private _isRecipientInStream;
    mapping(uint256 => mapping(address => uint256)) private _recipientRates;
    mapping(uint256 => mapping(address => uint256)) private _recipientTotalWithdrawn;
    mapping(uint256 => mapping(address => uint256)) private _recipientLastWithdraw;

    mapping(address => uint256[]) private _senderStreams;
    mapping(address => uint256[]) private _recipientStreams;

    uint256 public platformFeeBps;
    address public platformFeeRecipient;

    ISuperToken public superToken;
    IGDAv1Forwarder public gdaForwarder;

    address public engagementRewards;
    bool public engagementRewardsEnabled;
    mapping(address => address) public userInviter;

    event SuperfluidConfigUpdated(address indexed superToken, address indexed gdaForwarder);

    constructor() {}

    function initialize(
        address _platformFeeRecipient,
        address _owner,
        address _superToken,
        address _gdaForwarder
    ) public initializer {
        require(_platformFeeRecipient != address(0), "DripCoreSF: invalid fee recipient");
        require(_owner != address(0), "DripCoreSF: invalid owner");
        require(_superToken != address(0), "DripCoreSF: invalid super token");
        require(_gdaForwarder != address(0), "DripCoreSF: invalid forwarder");

        __ReentrancyGuard_init();
        __Ownable_init(_owner);

        platformFeeRecipient = _platformFeeRecipient;
        platformFeeBps = 50;
        superToken = ISuperToken(_superToken);
        gdaForwarder = IGDAv1Forwarder(_gdaForwarder);
    }

    function setSuperfluidConfig(address _superToken, address _gdaForwarder) external onlyOwner {
        require(_superToken != address(0), "DripCoreSF: invalid super token");
        require(_gdaForwarder != address(0), "DripCoreSF: invalid forwarder");
        superToken = ISuperToken(_superToken);
        gdaForwarder = IGDAv1Forwarder(_gdaForwarder);
        emit SuperfluidConfigUpdated(_superToken, _gdaForwarder);
    }

    function createStream(
        address[] calldata recipients,
        address token,
        uint256[] calldata amountsPerPeriod,
        uint256 periodSeconds,
        uint256 deposit,
        string calldata title,
        string calldata description
    ) external payable nonReentrant returns (uint256 streamId) {
        require(msg.value == 0, "DripCoreSF: native not supported");
        require(token == address(superToken), "DripCoreSF: token must be configured super token");
        require(recipients.length > 0, "DripCoreSF: recipients required");
        require(recipients.length == amountsPerPeriod.length, "DripCoreSF: mismatched arrays");
        require(deposit > 0, "DripCoreSF: invalid deposit");
        require(periodSeconds >= MIN_DURATION && periodSeconds <= MAX_DURATION, "DripCoreSF: invalid duration");
        require(bytes(title).length <= MAX_TITLE_LEN, "DripCoreSF: title too long");
        require(bytes(description).length <= MAX_DESCRIPTION_LEN, "DripCoreSF: description too long");

        uint256 totalPerPeriod;
        int256 totalFlowRateInt;
        for (uint256 i = 0; i < recipients.length; i++) {
            address recipient = recipients[i];
            require(recipient != address(0), "DripCoreSF: invalid recipient");
            require(recipient != msg.sender, "DripCoreSF: self recipient forbidden");
            require(!_isRecipientInStream[_streamIdCounter + 1][recipient], "DripCoreSF: duplicate recipient");
            require(amountsPerPeriod[i] > 0, "DripCoreSF: invalid amount");

            uint256 ratePerSecond = amountsPerPeriod[i] / periodSeconds;
            require(ratePerSecond > 0, "DripCoreSF: rate too small");

            totalPerPeriod += amountsPerPeriod[i];
            totalFlowRateInt += int256(ratePerSecond);
        }

        require(deposit >= totalPerPeriod, "DripCoreSF: insufficient deposit for period");
        require(totalFlowRateInt > 0 && totalFlowRateInt <= type(int96).max, "DripCoreSF: invalid total flow");

        uint256 fee = (deposit * platformFeeBps) / 10000;
        uint256 streamDeposit = deposit - fee;

        require(superToken.transferFrom(msg.sender, address(this), deposit), "DripCoreSF: transfer failed");
        if (fee > 0) {
            require(superToken.transfer(platformFeeRecipient, fee), "DripCoreSF: fee transfer failed");
        }

        streamId = ++_streamIdCounter;
        uint256 startTime = block.timestamp;
        uint256 endTime = startTime + periodSeconds;

        (bool poolCreated, ISuperfluidPool pool) = gdaForwarder.createPool(
            address(superToken),
            address(this),
            PoolConfig({
                transferabilityForUnitsOwner: false,
                distributionFromAnyAddress: true
            })
        );
        require(poolCreated, "DripCoreSF: pool creation failed");

        address[] memory recipientsArray = new address[](recipients.length);
        for (uint256 i = 0; i < recipients.length; i++) {
            address recipient = recipients[i];
            recipientsArray[i] = recipient;

            uint256 ratePerSecond = amountsPerPeriod[i] / periodSeconds;
            _recipientRates[streamId][recipient] = ratePerSecond;
            _recipientLastWithdraw[streamId][recipient] = startTime;
            _isRecipientInStream[streamId][recipient] = true;
            _recipientStreams[recipient].push(streamId);

            require(pool.updateMemberUnits(recipient, uint128(ratePerSecond)), "DripCoreSF: unit update failed");

            emit RecipientAdded(streamId, recipient, amountsPerPeriod[i], ratePerSecond);
        }

        _streams[streamId] = Stream({
            streamId: streamId,
            sender: msg.sender,
            recipients: recipientsArray,
            token: token,
            deposit: streamDeposit,
            startTime: startTime,
            endTime: endTime,
            status: StreamStatus.Active,
            rateLockUntil: 0,
            title: title,
            description: description
        });

        _streamRuntime[streamId] = StreamRuntime({
            pool: pool,
            totalFlowRate: int96(totalFlowRateInt),
            remainingBudget: streamDeposit,
            totalDistributedAccounting: 0,
            lastAccountingTimestamp: startTime
        });

        _senderStreams[msg.sender].push(streamId);

        require(
            gdaForwarder.distributeFlow(address(superToken), address(this), pool, int96(totalFlowRateInt), ""),
            "DripCoreSF: flow start failed"
        );

        emit StreamCreated(streamId, msg.sender, recipientsArray, token, streamDeposit, startTime, endTime, title, description);
    }

    function _syncAccounting(uint256 streamId) internal {
        Stream storage stream = _streams[streamId];
        StreamRuntime storage runtime = _streamRuntime[streamId];

        if (stream.streamId == 0) return;
        if (stream.status != StreamStatus.Active) {
            runtime.lastAccountingTimestamp = block.timestamp;
            return;
        }

        uint256 effectiveNow = block.timestamp;
        if (effectiveNow > stream.endTime) {
            effectiveNow = stream.endTime;
        }

        if (effectiveNow <= runtime.lastAccountingTimestamp) {
            return;
        }

        uint256 elapsed = effectiveNow - runtime.lastAccountingTimestamp;
        uint256 spent = elapsed * uint256(uint96(runtime.totalFlowRate));

        if (spent >= runtime.remainingBudget) {
            spent = runtime.remainingBudget;
            runtime.remainingBudget = 0;
        } else {
            runtime.remainingBudget -= spent;
        }

        runtime.totalDistributedAccounting += spent;
        runtime.lastAccountingTimestamp = effectiveNow;

        if (runtime.remainingBudget == 0 || effectiveNow >= stream.endTime) {
            gdaForwarder.distributeFlow(address(superToken), address(this), runtime.pool, 0, "");
            stream.status = StreamStatus.Completed;
            emit StreamCompleted(streamId);
        }
    }

    function getRecipientBalance(uint256 streamId, address recipient) external view returns (uint256 balance) {
        Stream memory stream = _streams[streamId];
        if (stream.streamId == 0 || !_isRecipientInStream[streamId][recipient]) {
            return 0;
        }
        (int256 claimable, ) = _streamRuntime[streamId].pool.getClaimableNow(recipient);
        if (claimable <= 0) return 0;
        return uint256(claimable);
    }

    function withdrawFromStream(uint256 streamId, address recipient) external nonReentrant returns (uint256 withdrawn) {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCoreSF: stream not found");
        require(_isRecipientInStream[streamId][recipient], "DripCoreSF: recipient not in stream");
        require(msg.sender == recipient, "DripCoreSF: only recipient can withdraw");
        require(
            stream.status == StreamStatus.Active ||
            stream.status == StreamStatus.Paused ||
            stream.status == StreamStatus.Completed,
            "DripCoreSF: stream not withdrawable"
        );

        _syncAccounting(streamId);

        uint256 beforeBal = superToken.balanceOf(recipient);
        require(_streamRuntime[streamId].pool.claimAll(recipient), "DripCoreSF: claim failed");
        uint256 afterBal = superToken.balanceOf(recipient);
        withdrawn = afterBal > beforeBal ? afterBal - beforeBal : 0;

        if (withdrawn > 0) {
            _recipientTotalWithdrawn[streamId][recipient] += withdrawn;
            _recipientLastWithdraw[streamId][recipient] = block.timestamp;
            emit StreamWithdrawn(streamId, recipient, withdrawn);
        }
    }

    function getRecipientInfo(uint256 streamId, address recipient) external view returns (RecipientInfo memory info) {
        Stream memory stream = _streams[streamId];
        require(stream.streamId != 0, "DripCoreSF: stream not found");
        require(_isRecipientInStream[streamId][recipient], "DripCoreSF: recipient not in stream");

        uint256 claimable;
        (int256 claimableSigned, ) = _streamRuntime[streamId].pool.getClaimableNow(recipient);
        if (claimableSigned > 0) {
            claimable = uint256(claimableSigned);
        }

        info = RecipientInfo({
            recipient: recipient,
            ratePerSecond: _recipientRates[streamId][recipient],
            totalWithdrawn: _recipientTotalWithdrawn[streamId][recipient],
            lastWithdrawTime: _recipientLastWithdraw[streamId][recipient],
            currentAccrued: claimable
        });
    }

    function getAllRecipientsInfo(uint256 streamId) external view returns (RecipientInfo[] memory recipients) {
        Stream memory stream = _streams[streamId];
        require(stream.streamId != 0, "DripCoreSF: stream not found");

        recipients = new RecipientInfo[](stream.recipients.length);
        for (uint256 i = 0; i < stream.recipients.length; i++) {
            address recipient = stream.recipients[i];

            uint256 claimable;
            (int256 claimableSigned, ) = _streamRuntime[streamId].pool.getClaimableNow(recipient);
            if (claimableSigned > 0) {
                claimable = uint256(claimableSigned);
            }

            recipients[i] = RecipientInfo({
                recipient: recipient,
                ratePerSecond: _recipientRates[streamId][recipient],
                totalWithdrawn: _recipientTotalWithdrawn[streamId][recipient],
                lastWithdrawTime: _recipientLastWithdraw[streamId][recipient],
                currentAccrued: claimable
            });
        }
    }

    function pauseStream(uint256 streamId) external {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCoreSF: stream not found");
        require(stream.sender == msg.sender || msg.sender == owner(), "DripCoreSF: unauthorized");
        require(stream.status == StreamStatus.Active, "DripCoreSF: stream not active");

        _syncAccounting(streamId);

        require(
            gdaForwarder.distributeFlow(address(superToken), address(this), _streamRuntime[streamId].pool, 0, ""),
            "DripCoreSF: flow pause failed"
        );

        stream.status = StreamStatus.Paused;
        emit StreamPaused(streamId, msg.sender);
    }

    function resumeStream(uint256 streamId) external {
        Stream storage stream = _streams[streamId];
        StreamRuntime storage runtime = _streamRuntime[streamId];

        require(stream.streamId != 0, "DripCoreSF: stream not found");
        require(stream.sender == msg.sender || msg.sender == owner(), "DripCoreSF: unauthorized");
        require(stream.status == StreamStatus.Paused, "DripCoreSF: stream not paused");
        require(runtime.remainingBudget > 0, "DripCoreSF: no remaining budget");
        require(block.timestamp < stream.endTime, "DripCoreSF: stream already ended");

        runtime.lastAccountingTimestamp = block.timestamp;
        require(
            gdaForwarder.distributeFlow(address(superToken), address(this), runtime.pool, runtime.totalFlowRate, ""),
            "DripCoreSF: flow resume failed"
        );

        stream.status = StreamStatus.Active;
        emit StreamResumed(streamId, msg.sender);
    }

    function cancelStream(uint256 streamId) external nonReentrant {
        Stream storage stream = _streams[streamId];
        StreamRuntime storage runtime = _streamRuntime[streamId];

        require(stream.streamId != 0, "DripCoreSF: stream not found");
        require(stream.sender == msg.sender || msg.sender == owner(), "DripCoreSF: unauthorized");
        require(stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused, "DripCoreSF: stream not cancellable");

        _syncAccounting(streamId);

        require(
            gdaForwarder.distributeFlow(address(superToken), address(this), runtime.pool, 0, ""),
            "DripCoreSF: flow stop failed"
        );

        uint256 refundAmount = runtime.remainingBudget;
        runtime.remainingBudget = 0;

        stream.status = StreamStatus.Cancelled;

        if (refundAmount > 0) {
            require(superToken.transfer(stream.sender, refundAmount), "DripCoreSF: refund failed");
        }

        emit StreamCancelled(streamId, msg.sender, refundAmount);
    }

    function lockStreamRate(uint256 streamId, uint256 lockDuration) external {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCoreSF: stream not found");
        require(stream.sender == msg.sender || msg.sender == owner(), "DripCoreSF: unauthorized");
        stream.rateLockUntil = block.timestamp + lockDuration;
        emit StreamRateLocked(streamId, stream.rateLockUntil);
    }

    function _requireRateUnlocked(Stream memory stream) internal view {
        require(stream.rateLockUntil <= block.timestamp, "DripCoreSF: rate locked");
    }

    function extendStream(
        uint256 streamId,
        uint256 newEndTime,
        uint256 depositAmount
    ) external payable nonReentrant {
        require(msg.value == 0, "DripCoreSF: native not supported");
        Stream storage stream = _streams[streamId];
        StreamRuntime storage runtime = _streamRuntime[streamId];

        require(stream.streamId != 0, "DripCoreSF: stream not found");
        require(stream.sender == msg.sender, "DripCoreSF: only sender");
        require(stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused, "DripCoreSF: stream immutable");

        _syncAccounting(streamId);

        uint256 addedDeposit;
        if (depositAmount > 0) {
            require(superToken.transferFrom(msg.sender, address(this), depositAmount), "DripCoreSF: deposit transfer failed");
            runtime.remainingBudget += depositAmount;
            stream.deposit += depositAmount;
            addedDeposit = depositAmount;
        }

        if (newEndTime > stream.endTime) {
            stream.endTime = newEndTime;
        }

        emit StreamExtended(streamId, stream.endTime, addedDeposit);
    }

    function addRecipient(
        uint256 streamId,
        address recipient,
        uint256 amountPerPeriod,
        uint256 additionalDeposit
    ) external payable nonReentrant {
        require(msg.value == 0, "DripCoreSF: native not supported");
        Stream storage stream = _streams[streamId];
        StreamRuntime storage runtime = _streamRuntime[streamId];

        require(stream.streamId != 0, "DripCoreSF: stream not found");
        require(stream.sender == msg.sender, "DripCoreSF: only sender");
        require(stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused, "DripCoreSF: stream immutable");
        require(recipient != address(0) && recipient != stream.sender, "DripCoreSF: invalid recipient");
        require(!_isRecipientInStream[streamId][recipient], "DripCoreSF: recipient exists");
        _requireRateUnlocked(stream);

        _syncAccounting(streamId);

        uint256 periodSeconds = stream.endTime > stream.startTime ? (stream.endTime - stream.startTime) : 0;
        require(periodSeconds > 0, "DripCoreSF: invalid period");

        uint256 ratePerSecond = amountPerPeriod / periodSeconds;
        require(ratePerSecond > 0, "DripCoreSF: rate too small");

        address[] memory oldRecipients = stream.recipients;
        address[] memory newRecipients = new address[](oldRecipients.length + 1);
        for (uint256 i = 0; i < oldRecipients.length; i++) {
            newRecipients[i] = oldRecipients[i];
        }
        newRecipients[oldRecipients.length] = recipient;
        stream.recipients = newRecipients;

        _isRecipientInStream[streamId][recipient] = true;
        _recipientRates[streamId][recipient] = ratePerSecond;
        _recipientLastWithdraw[streamId][recipient] = block.timestamp;
        _recipientStreams[recipient].push(streamId);

        require(runtime.pool.updateMemberUnits(recipient, uint128(ratePerSecond)), "DripCoreSF: unit update failed");

        int96 newFlowRate = runtime.totalFlowRate + int96(int256(ratePerSecond));
        runtime.totalFlowRate = newFlowRate;

        if (additionalDeposit > 0) {
            require(superToken.transferFrom(msg.sender, address(this), additionalDeposit), "DripCoreSF: add deposit failed");
            runtime.remainingBudget += additionalDeposit;
            stream.deposit += additionalDeposit;
        }

        if (stream.status == StreamStatus.Active) {
            require(
                gdaForwarder.distributeFlow(address(superToken), address(this), runtime.pool, newFlowRate, ""),
                "DripCoreSF: flow update failed"
            );
        }

        emit RecipientAdded(streamId, recipient, amountPerPeriod, ratePerSecond);
    }

    function removeRecipient(uint256 streamId, address recipient) external nonReentrant {
        Stream storage stream = _streams[streamId];
        StreamRuntime storage runtime = _streamRuntime[streamId];

        require(stream.streamId != 0, "DripCoreSF: stream not found");
        require(stream.sender == msg.sender, "DripCoreSF: only sender");
        require(stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused, "DripCoreSF: stream immutable");
        require(_isRecipientInStream[streamId][recipient], "DripCoreSF: recipient missing");
        _requireRateUnlocked(stream);

        _syncAccounting(streamId);

        uint256 rate = _recipientRates[streamId][recipient];
        _recipientRates[streamId][recipient] = 0;
        _isRecipientInStream[streamId][recipient] = false;

        require(runtime.pool.updateMemberUnits(recipient, 0), "DripCoreSF: unit clear failed");

        runtime.totalFlowRate = runtime.totalFlowRate - int96(int256(rate));

        address[] memory oldRecipients = stream.recipients;
        uint256 n = oldRecipients.length;
        address[] memory compact = new address[](n - 1);
        uint256 k = 0;
        for (uint256 i = 0; i < n; i++) {
            if (oldRecipients[i] != recipient) {
                compact[k++] = oldRecipients[i];
            }
        }
        stream.recipients = compact;

        if (stream.status == StreamStatus.Active) {
            require(
                gdaForwarder.distributeFlow(address(superToken), address(this), runtime.pool, runtime.totalFlowRate, ""),
                "DripCoreSF: flow update failed"
            );
        }

        emit RecipientRemoved(streamId, recipient, 0);
    }

    function updateRecipientRate(
        uint256 streamId,
        address recipient,
        uint256 newAmountPerPeriod,
        uint256 additionalDeposit
    ) external payable nonReentrant {
        require(msg.value == 0, "DripCoreSF: native not supported");
        Stream storage stream = _streams[streamId];
        StreamRuntime storage runtime = _streamRuntime[streamId];

        require(stream.streamId != 0, "DripCoreSF: stream not found");
        require(stream.sender == msg.sender, "DripCoreSF: only sender");
        require(stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused, "DripCoreSF: stream immutable");
        require(_isRecipientInStream[streamId][recipient], "DripCoreSF: recipient missing");
        _requireRateUnlocked(stream);

        _syncAccounting(streamId);

        uint256 periodSeconds = stream.endTime > stream.startTime ? (stream.endTime - stream.startTime) : 0;
        require(periodSeconds > 0, "DripCoreSF: invalid period");

        uint256 oldRate = _recipientRates[streamId][recipient];
        uint256 newRate = newAmountPerPeriod / periodSeconds;
        require(newRate > 0, "DripCoreSF: rate too small");

        _recipientRates[streamId][recipient] = newRate;
        require(runtime.pool.updateMemberUnits(recipient, uint128(newRate)), "DripCoreSF: unit update failed");

        runtime.totalFlowRate = runtime.totalFlowRate - int96(int256(oldRate)) + int96(int256(newRate));

        if (additionalDeposit > 0) {
            require(superToken.transferFrom(msg.sender, address(this), additionalDeposit), "DripCoreSF: add deposit failed");
            runtime.remainingBudget += additionalDeposit;
            stream.deposit += additionalDeposit;
        }

        if (stream.status == StreamStatus.Active) {
            require(
                gdaForwarder.distributeFlow(address(superToken), address(this), runtime.pool, runtime.totalFlowRate, ""),
                "DripCoreSF: flow update failed"
            );
        }

        emit RecipientRateUpdated(streamId, recipient, oldRate, newRate);
    }

    function getStream(uint256 streamId) external view returns (Stream memory stream) {
        stream = _streams[streamId];
        require(stream.streamId != 0, "DripCoreSF: stream not found");
    }

    function getSenderStreams(address sender) external view returns (uint256[] memory streamIds) {
        return _senderStreams[sender];
    }

    function getRecipientStreams(address recipient) external view returns (uint256[] memory streamIds) {
        return _recipientStreams[recipient];
    }

    function getUserSentStreams(address user) external view returns (Stream[] memory streams) {
        uint256[] memory ids = _senderStreams[user];
        streams = new Stream[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
            streams[i] = _streams[ids[i]];
        }
    }

    function getUserReceivedStreams(address user) external view returns (Stream[] memory streams) {
        uint256[] memory ids = _recipientStreams[user];
        streams = new Stream[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
            streams[i] = _streams[ids[i]];
        }
    }

    function setPlatformFee(uint256 newFeeBps) external onlyOwner {
        require(newFeeBps <= 1000, "DripCoreSF: fee too high");
        platformFeeBps = newFeeBps;
    }

    function setPlatformFeeRecipient(address newRecipient) external onlyOwner {
        require(newRecipient != address(0), "DripCoreSF: invalid recipient");
        platformFeeRecipient = newRecipient;
    }

    function setEngagementRewards(address _engagementRewards) external onlyOwner {
        engagementRewards = _engagementRewards;
    }

    function setEngagementRewardsEnabled(bool _enabled) external onlyOwner {
        engagementRewardsEnabled = _enabled;
    }

    function setInviter(address inviter) external {
        if (inviter == address(0) || inviter == msg.sender) {
            return;
        }
        if (userInviter[msg.sender] == address(0)) {
            userInviter[msg.sender] = inviter;
        }
    }

    function claimEngagementReward(
        address,
        uint256,
        bytes calldata
    ) external pure returns (bool) {
        return false;
    }

    function emergencyWithdrawAll(address[] calldata tokens, address payable to) external onlyOwner {
        require(to != address(0), "DripCoreSF: invalid recipient");
        for (uint256 i = 0; i < tokens.length; i++) {
            address token = tokens[i];
            if (token == address(0)) {
                continue;
            }
            uint256 bal = ISuperToken(token).balanceOf(address(this));
            if (bal > 0) {
                ISuperToken(token).transfer(to, bal);
            }
        }
        if (address(this).balance > 0) {
            (bool ok, ) = to.call{value: address(this).balance}("");
            require(ok, "DripCoreSF: native transfer failed");
        }
    }

    function getContractBalances(address[] calldata tokens) external view returns (uint256[] memory balances) {
        balances = new uint256[](tokens.length);
        for (uint256 i = 0; i < tokens.length; i++) {
            if (tokens[i] == address(0)) {
                balances[i] = address(this).balance;
            } else {
                balances[i] = ISuperToken(tokens[i]).balanceOf(address(this));
            }
        }
    }

    receive() external payable {}
}

contracts/DripCoreSuperfluidCFA.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "./interfaces/IDrip.sol";

interface ISuperToken {
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface ICFAv1Forwarder {
    function createFlow(
        address token,
        address sender,
        address receiver,
        int96 flowRate,
        bytes calldata userData
    ) external returns (bool);

    function updateFlow(
        address token,
        address sender,
        address receiver,
        int96 flowRate,
        bytes calldata userData
    ) external returns (bool);

    function deleteFlow(
        address token,
        address sender,
        address receiver,
        bytes calldata userData
    ) external returns (bool);

    function getFlowrate(
        address token,
        address sender,
        address receiver
    ) external view returns (int96 flowRate);
}

contract DripCoreSuperfluidCFA is IDrip, Initializable, ReentrancyGuardUpgradeable, OwnableUpgradeable {
    uint256 public constant MIN_DURATION = 3600;
    uint256 public constant MAX_DURATION = 315360000;
    uint256 public constant MAX_TITLE_LEN = 120;
    uint256 public constant MAX_DESCRIPTION_LEN = 1024;

    struct StreamRuntime {
        int96 totalFlowRate;
        uint256 remainingBudget;
        uint256 totalDistributedAccounting;
        uint256 lastAccountingTimestamp;
    }

    uint256 private _streamIdCounter;

    mapping(uint256 => Stream) private _streams;
    mapping(uint256 => StreamRuntime) private _streamRuntime;

    mapping(uint256 => mapping(address => bool)) private _isRecipientInStream;
    mapping(uint256 => mapping(address => uint256)) private _recipientRates;
    mapping(uint256 => mapping(address => uint256)) private _recipientTotalStreamed;
    mapping(uint256 => mapping(address => uint256)) private _recipientStartTime;
    mapping(uint256 => mapping(address => bool)) private _isRecipientPaused;

    mapping(address => uint256[]) private _senderStreams;
    mapping(address => uint256[]) private _recipientStreams;

    uint256 public platformFeeBps;
    address public platformFeeRecipient;

    ISuperToken public superToken;
    ICFAv1Forwarder public cfaForwarder;

    address public engagementRewards;
    bool public engagementRewardsEnabled;
    mapping(address => address) public userInviter;

    event SuperfluidConfigUpdated(address indexed superToken, address indexed cfaForwarder);

    constructor() {}

    function initialize(
        address _platformFeeRecipient,
        address _owner,
        address _superToken,
        address _cfaForwarder
    ) public initializer {
        require(_platformFeeRecipient != address(0), "DripCoreCFA: invalid fee recipient");
        require(_owner != address(0), "DripCoreCFA: invalid owner");
        require(_superToken != address(0), "DripCoreCFA: invalid super token");
        require(_cfaForwarder != address(0), "DripCoreCFA: invalid forwarder");

        __ReentrancyGuard_init();
        __Ownable_init(_owner);

        platformFeeRecipient = _platformFeeRecipient;
        platformFeeBps = 50;
        superToken = ISuperToken(_superToken);
        cfaForwarder = ICFAv1Forwarder(_cfaForwarder);
    }

    function setSuperfluidConfig(address _superToken, address _cfaForwarder) external onlyOwner {
        require(_superToken != address(0), "DripCoreCFA: invalid super token");
        require(_cfaForwarder != address(0), "DripCoreCFA: invalid forwarder");
        superToken = ISuperToken(_superToken);
        cfaForwarder = ICFAv1Forwarder(_cfaForwarder);
        emit SuperfluidConfigUpdated(_superToken, _cfaForwarder);
    }

    function createStream(
        address[] calldata recipients,
        address token,
        uint256[] calldata amountsPerPeriod,
        uint256 periodSeconds,
        uint256 deposit,
        string calldata title,
        string calldata description
    ) external payable nonReentrant returns (uint256 streamId) {
        require(msg.value == 0, "DripCoreCFA: native not supported");
        require(token == address(superToken), "DripCoreCFA: token must be configured super token");
        require(recipients.length > 0, "DripCoreCFA: recipients required");
        require(recipients.length == amountsPerPeriod.length, "DripCoreCFA: mismatched arrays");
        require(deposit > 0, "DripCoreCFA: invalid deposit");
        require(periodSeconds >= MIN_DURATION && periodSeconds <= MAX_DURATION, "DripCoreCFA: invalid duration");
        require(bytes(title).length <= MAX_TITLE_LEN, "DripCoreCFA: title too long");
        require(bytes(description).length <= MAX_DESCRIPTION_LEN, "DripCoreCFA: description too long");

        uint256 totalPerPeriod;
        int256 totalFlowRateInt;
        for (uint256 i = 0; i < recipients.length; i++) {
            address recipient = recipients[i];
            require(recipient != address(0), "DripCoreCFA: invalid recipient");
            require(recipient != msg.sender, "DripCoreCFA: self recipient forbidden");
            require(!_isRecipientInStream[_streamIdCounter + 1][recipient], "DripCoreCFA: duplicate recipient");
            require(amountsPerPeriod[i] > 0, "DripCoreCFA: invalid amount");

            uint256 ratePerSecond = amountsPerPeriod[i] / periodSeconds;
            require(ratePerSecond > 0, "DripCoreCFA: rate too small");

            totalPerPeriod += amountsPerPeriod[i];
            totalFlowRateInt += int256(ratePerSecond);
        }

        require(deposit >= totalPerPeriod, "DripCoreCFA: insufficient deposit for period");
        require(totalFlowRateInt > 0 && totalFlowRateInt <= type(int96).max, "DripCoreCFA: invalid total flow");

        uint256 fee = (deposit * platformFeeBps) / 10000;
        uint256 streamDeposit = deposit - fee;

        require(superToken.transferFrom(msg.sender, address(this), deposit), "DripCoreCFA: transfer failed");
        if (fee > 0) {
            require(superToken.transfer(platformFeeRecipient, fee), "DripCoreCFA: fee transfer failed");
        }

        streamId = ++_streamIdCounter;
        uint256 startTime = block.timestamp;
        uint256 endTime = startTime + periodSeconds;

        address[] memory recipientsArray = new address[](recipients.length);
        for (uint256 i = 0; i < recipients.length; i++) {
            address recipient = recipients[i];
            recipientsArray[i] = recipient;

            uint256 ratePerSecond = amountsPerPeriod[i] / periodSeconds;
            _recipientRates[streamId][recipient] = ratePerSecond;
            _recipientStartTime[streamId][recipient] = startTime;
            _isRecipientInStream[streamId][recipient] = true;
            _recipientStreams[recipient].push(streamId);

            // Create individual CFA stream to this recipient
            require(
                cfaForwarder.createFlow(
                    address(superToken),
                    address(this),
                    recipient,
                    int96(int256(ratePerSecond)),
                    ""
                ),
                "DripCoreCFA: flow creation failed"
            );

            emit RecipientAdded(streamId, recipient, amountsPerPeriod[i], ratePerSecond);
        }

        _streams[streamId] = Stream({
            streamId: streamId,
            sender: msg.sender,
            recipients: recipientsArray,
            token: token,
            deposit: streamDeposit,
            startTime: startTime,
            endTime: endTime,
            status: StreamStatus.Active,
            rateLockUntil: 0,
            title: title,
            description: description
        });

        _streamRuntime[streamId] = StreamRuntime({
            totalFlowRate: int96(totalFlowRateInt),
            remainingBudget: streamDeposit,
            totalDistributedAccounting: 0,
            lastAccountingTimestamp: startTime
        });

        _senderStreams[msg.sender].push(streamId);

        emit StreamCreated(streamId, msg.sender, recipientsArray, token, streamDeposit, startTime, endTime, title, description);
    }

    function _syncAccounting(uint256 streamId) internal {
        Stream storage stream = _streams[streamId];
        StreamRuntime storage runtime = _streamRuntime[streamId];

        if (stream.streamId == 0) return;
        if (stream.status != StreamStatus.Active) {
            runtime.lastAccountingTimestamp = block.timestamp;
            return;
        }

        uint256 effectiveNow = block.timestamp;
        if (effectiveNow > stream.endTime) {
            effectiveNow = stream.endTime;
        }

        if (effectiveNow <= runtime.lastAccountingTimestamp) {
            return;
        }

        uint256 elapsed = effectiveNow - runtime.lastAccountingTimestamp;
        uint256 spent = elapsed * uint256(uint96(runtime.totalFlowRate));

        if (spent >= runtime.remainingBudget) {
            spent = runtime.remainingBudget;
            runtime.remainingBudget = 0;
        } else {
            runtime.remainingBudget -= spent;
        }

        runtime.totalDistributedAccounting += spent;
        runtime.lastAccountingTimestamp = effectiveNow;

        if (runtime.remainingBudget == 0 || effectiveNow >= stream.endTime) {
            // Stop all flows
            for (uint256 i = 0; i < stream.recipients.length; i++) {
                address recipient = stream.recipients[i];
                if (_isRecipientInStream[streamId][recipient]) {
                    cfaForwarder.deleteFlow(address(superToken), address(this), recipient, "");
                }
            }
            stream.status = StreamStatus.Completed;
            emit StreamCompleted(streamId);
        }
    }

    function getRecipientBalance(uint256 streamId, address recipient) external view returns (uint256 balance) {
        Stream memory stream = _streams[streamId];
        if (stream.streamId == 0 || !_isRecipientInStream[streamId][recipient]) {
            return 0;
        }

        // CFA streams directly to recipient - calculate accrued amount
        uint256 rate = _recipientRates[streamId][recipient];
        if (rate == 0) return 0;

        uint256 startTime = _recipientStartTime[streamId][recipient];
        uint256 elapsed = block.timestamp > startTime ? block.timestamp - startTime : 0;
        return elapsed * rate;
    }

    function withdrawFromStream(uint256 streamId, address recipient) external nonReentrant returns (uint256 withdrawn) {
        // CFA automatically streams to recipient - this is a no-op for compatibility
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCoreCFA: stream not found");
        require(_isRecipientInStream[streamId][recipient], "DripCoreCFA: recipient not in stream");
        require(msg.sender == recipient, "DripCoreCFA: only recipient can call");

        _syncAccounting(streamId);

        // No action needed - tokens already streaming to recipient
        // Return 0 since there's nothing to withdraw (already in their balance)
        return 0;
    }

    function getRecipientInfo(uint256 streamId, address recipient) external view returns (RecipientInfo memory info) {
        Stream memory stream = _streams[streamId];
        require(stream.streamId != 0, "DripCoreCFA: stream not found");
        require(_isRecipientInStream[streamId][recipient], "DripCoreCFA: recipient not in stream");

        uint256 rate = _recipientRates[streamId][recipient];
        uint256 startTime = _recipientStartTime[streamId][recipient];
        uint256 elapsed = block.timestamp > startTime ? block.timestamp - startTime : 0;
        uint256 totalStreamed = elapsed * rate;

        info = RecipientInfo({
            recipient: recipient,
            ratePerSecond: rate,
            totalWithdrawn: totalStreamed, // For CFA, this is total streamed
            lastWithdrawTime: block.timestamp, // Always current time for CFA
            currentAccrued: 0 // Always 0 since auto-streaming
        });
    }

    function getAllRecipientsInfo(uint256 streamId) external view returns (RecipientInfo[] memory recipients) {
        Stream memory stream = _streams[streamId];
        require(stream.streamId != 0, "DripCoreCFA: stream not found");

        recipients = new RecipientInfo[](stream.recipients.length);
        for (uint256 i = 0; i < stream.recipients.length; i++) {
            address recipient = stream.recipients[i];

            uint256 rate = _recipientRates[streamId][recipient];
            uint256 startTime = _recipientStartTime[streamId][recipient];
            uint256 elapsed = block.timestamp > startTime ? block.timestamp - startTime : 0;
            uint256 totalStreamed = elapsed * rate;

            recipients[i] = RecipientInfo({
                recipient: recipient,
                ratePerSecond: rate,
                totalWithdrawn: totalStreamed,
                lastWithdrawTime: block.timestamp,
                currentAccrued: 0
            });
        }
    }

    function pauseStream(uint256 streamId) external {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCoreCFA: stream not found");
        require(stream.sender == msg.sender || msg.sender == owner(), "DripCoreCFA: unauthorized");
        require(stream.status == StreamStatus.Active, "DripCoreCFA: stream not active");

        _syncAccounting(streamId);

        // Delete flows to pause (deleteFlow is the Superfluid way for forwarders)
        for (uint256 i = 0; i < stream.recipients.length; i++) {
            address recipient = stream.recipients[i];
            if (_isRecipientInStream[streamId][recipient] && !_isRecipientPaused[streamId][recipient]) {
                require(
                    cfaForwarder.deleteFlow(address(superToken), address(this), recipient, ""),
                    "DripCoreCFA: flow deletion failed"
                );
                _isRecipientPaused[streamId][recipient] = true;
            }
        }

        stream.status = StreamStatus.Paused;
        emit StreamPaused(streamId, msg.sender);
    }

    function resumeStream(uint256 streamId) external {
        Stream storage stream = _streams[streamId];
        StreamRuntime storage runtime = _streamRuntime[streamId];

        require(stream.streamId != 0, "DripCoreCFA: stream not found");
        require(stream.sender == msg.sender || msg.sender == owner(), "DripCoreCFA: unauthorized");
        require(stream.status == StreamStatus.Paused, "DripCoreCFA: stream not paused");
        require(runtime.remainingBudget > 0, "DripCoreCFA: no remaining budget");
        require(block.timestamp < stream.endTime, "DripCoreCFA: stream already ended");

        runtime.lastAccountingTimestamp = block.timestamp;

        // Recreate flows to resume (createFlow after deleteFlow is the pattern for forwarders)
        for (uint256 i = 0; i < stream.recipients.length; i++) {
            address recipient = stream.recipients[i];
            if (_isRecipientInStream[streamId][recipient] && _isRecipientPaused[streamId][recipient]) {
                uint256 rate = _recipientRates[streamId][recipient];
                require(
                    cfaForwarder.createFlow(
                        address(superToken),
                        address(this),
                        recipient,
                        int96(int256(rate)),
                        ""
                    ),
                    "DripCoreCFA: flow creation failed"
                );
                _isRecipientPaused[streamId][recipient] = false;
                _recipientStartTime[streamId][recipient] = block.timestamp;
            }
        }

        stream.status = StreamStatus.Active;
        emit StreamResumed(streamId, msg.sender);
    }

    function cancelStream(uint256 streamId) external nonReentrant {
        Stream storage stream = _streams[streamId];
        StreamRuntime storage runtime = _streamRuntime[streamId];

        require(stream.streamId != 0, "DripCoreCFA: stream not found");
        require(stream.sender == msg.sender || msg.sender == owner(), "DripCoreCFA: unauthorized");
        require(stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused, "DripCoreCFA: stream not cancellable");

        _syncAccounting(streamId);

        // Delete all flows
        for (uint256 i = 0; i < stream.recipients.length; i++) {
            address recipient = stream.recipients[i];
            if (_isRecipientInStream[streamId][recipient]) {
                cfaForwarder.deleteFlow(address(superToken), address(this), recipient, "");
            }
        }

        uint256 refundAmount = runtime.remainingBudget;
        runtime.remainingBudget = 0;

        stream.status = StreamStatus.Cancelled;

        if (refundAmount > 0) {
            require(superToken.transfer(stream.sender, refundAmount), "DripCoreCFA: refund failed");
        }

        emit StreamCancelled(streamId, msg.sender, refundAmount);
    }

    function pauseRecipient(uint256 streamId, address recipient) external {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCoreCFA: stream not found");
        require(stream.sender == msg.sender || msg.sender == owner(), "DripCoreCFA: unauthorized");
        require(_isRecipientInStream[streamId][recipient], "DripCoreCFA: recipient not in stream");
        require(!_isRecipientPaused[streamId][recipient], "DripCoreCFA: already paused");
        require(stream.status == StreamStatus.Active, "DripCoreCFA: stream not active");

        _syncAccounting(streamId);

        // Delete flow to pause this recipient
        require(
            cfaForwarder.deleteFlow(address(superToken), address(this), recipient, ""),
            "DripCoreCFA: flow deletion failed"
        );

        _isRecipientPaused[streamId][recipient] = true;
        emit RecipientRemoved(streamId, recipient, 0); // Reuse event for now
    }

    function resumeRecipient(uint256 streamId, address recipient) external {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCoreCFA: stream not found");
        require(stream.sender == msg.sender || msg.sender == owner(), "DripCoreCFA: unauthorized");
        require(_isRecipientInStream[streamId][recipient], "DripCoreCFA: recipient not in stream");
        require(_isRecipientPaused[streamId][recipient], "DripCoreCFA: not paused");
        require(stream.status == StreamStatus.Active, "DripCoreCFA: stream not active");

        _syncAccounting(streamId);

        uint256 rate = _recipientRates[streamId][recipient];
        require(rate > 0, "DripCoreCFA: invalid rate");

        // Recreate flow to resume this recipient
        require(
            cfaForwarder.createFlow(
                address(superToken),
                address(this),
                recipient,
                int96(int256(rate)),
                ""
            ),
            "DripCoreCFA: flow creation failed"
        );

        _isRecipientPaused[streamId][recipient] = false;
        _recipientStartTime[streamId][recipient] = block.timestamp; // Reset start time
        emit RecipientAdded(streamId, recipient, 0, rate); // Reuse event for now
    }

    function isRecipientPaused(uint256 streamId, address recipient) external view returns (bool) {
        return _isRecipientPaused[streamId][recipient];
    }

    function lockStreamRate(uint256 streamId, uint256 lockDuration) external {
        Stream storage stream = _streams[streamId];
        require(stream.streamId != 0, "DripCoreCFA: stream not found");
        require(stream.sender == msg.sender || msg.sender == owner(), "DripCoreCFA: unauthorized");
        stream.rateLockUntil = block.timestamp + lockDuration;
        emit StreamRateLocked(streamId, stream.rateLockUntil);
    }

    function _requireRateUnlocked(Stream memory stream) internal view {
        require(stream.rateLockUntil <= block.timestamp, "DripCoreCFA: rate locked");
    }

    function extendStream(
        uint256 streamId,
        uint256 newEndTime,
        uint256 depositAmount
    ) external payable nonReentrant {
        require(msg.value == 0, "DripCoreCFA: native not supported");
        Stream storage stream = _streams[streamId];
        StreamRuntime storage runtime = _streamRuntime[streamId];

        require(stream.streamId != 0, "DripCoreCFA: stream not found");
        require(stream.sender == msg.sender, "DripCoreCFA: only sender");
        require(stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused, "DripCoreCFA: stream immutable");

        _syncAccounting(streamId);

        uint256 addedDeposit;
        if (depositAmount > 0) {
            require(superToken.transferFrom(msg.sender, address(this), depositAmount), "DripCoreCFA: deposit transfer failed");
            runtime.remainingBudget += depositAmount;
            stream.deposit += depositAmount;
            addedDeposit = depositAmount;
        }

        if (newEndTime > stream.endTime) {
            stream.endTime = newEndTime;
        }

        emit StreamExtended(streamId, stream.endTime, addedDeposit);
    }

    function addRecipient(
        uint256 streamId,
        address recipient,
        uint256 amountPerPeriod,
        uint256 additionalDeposit
    ) external payable nonReentrant {
        require(msg.value == 0, "DripCoreCFA: native not supported");
        Stream storage stream = _streams[streamId];
        StreamRuntime storage runtime = _streamRuntime[streamId];

        require(stream.streamId != 0, "DripCoreCFA: stream not found");
        require(stream.sender == msg.sender, "DripCoreCFA: only sender");
        require(stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused, "DripCoreCFA: stream immutable");
        require(recipient != address(0) && recipient != stream.sender, "DripCoreCFA: invalid recipient");
        require(!_isRecipientInStream[streamId][recipient], "DripCoreCFA: recipient exists");
        _requireRateUnlocked(stream);

        _syncAccounting(streamId);

        uint256 periodSeconds = stream.endTime > stream.startTime ? (stream.endTime - stream.startTime) : 0;
        require(periodSeconds > 0, "DripCoreCFA: invalid period");

        uint256 ratePerSecond = amountPerPeriod / periodSeconds;
        require(ratePerSecond > 0, "DripCoreCFA: rate too small");

        address[] memory oldRecipients = stream.recipients;
        address[] memory newRecipients = new address[](oldRecipients.length + 1);
        for (uint256 i = 0; i < oldRecipients.length; i++) {
            newRecipients[i] = oldRecipients[i];
        }
        newRecipients[oldRecipients.length] = recipient;
        stream.recipients = newRecipients;

        _isRecipientInStream[streamId][recipient] = true;
        _recipientRates[streamId][recipient] = ratePerSecond;
        _recipientStartTime[streamId][recipient] = block.timestamp;
        _recipientStreams[recipient].push(streamId);

        int96 newFlowRate = runtime.totalFlowRate + int96(int256(ratePerSecond));
        runtime.totalFlowRate = newFlowRate;

        if (additionalDeposit > 0) {
            require(superToken.transferFrom(msg.sender, address(this), additionalDeposit), "DripCoreCFA: add deposit failed");
            runtime.remainingBudget += additionalDeposit;
            stream.deposit += additionalDeposit;
        }

        if (stream.status == StreamStatus.Active) {
            require(
                cfaForwarder.createFlow(
                    address(superToken),
                    address(this),
                    recipient,
                    int96(int256(ratePerSecond)),
                    ""
                ),
                "DripCoreCFA: flow creation failed"
            );
        }

        emit RecipientAdded(streamId, recipient, amountPerPeriod, ratePerSecond);
    }

    function removeRecipient(uint256 streamId, address recipient) external nonReentrant {
        Stream storage stream = _streams[streamId];
        StreamRuntime storage runtime = _streamRuntime[streamId];

        require(stream.streamId != 0, "DripCoreCFA: stream not found");
        require(stream.sender == msg.sender, "DripCoreCFA: only sender");
        require(stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused, "DripCoreCFA: stream immutable");
        require(_isRecipientInStream[streamId][recipient], "DripCoreCFA: recipient missing");
        _requireRateUnlocked(stream);

        _syncAccounting(streamId);

        uint256 rate = _recipientRates[streamId][recipient];
        _recipientRates[streamId][recipient] = 0;
        _isRecipientInStream[streamId][recipient] = false;

        runtime.totalFlowRate = runtime.totalFlowRate - int96(int256(rate));

        address[] memory oldRecipients = stream.recipients;
        uint256 n = oldRecipients.length;
        address[] memory compact = new address[](n - 1);
        uint256 k = 0;
        for (uint256 i = 0; i < n; i++) {
            if (oldRecipients[i] != recipient) {
                compact[k++] = oldRecipients[i];
            }
        }
        stream.recipients = compact;

        if (stream.status == StreamStatus.Active) {
            require(
                cfaForwarder.deleteFlow(address(superToken), address(this), recipient, ""),
                "DripCoreCFA: flow deletion failed"
            );
        }

        emit RecipientRemoved(streamId, recipient, 0);
    }

    function updateRecipientRate(
        uint256 streamId,
        address recipient,
        uint256 newAmountPerPeriod,
        uint256 additionalDeposit
    ) external payable nonReentrant {
        require(msg.value == 0, "DripCoreCFA: native not supported");
        Stream storage stream = _streams[streamId];
        StreamRuntime storage runtime = _streamRuntime[streamId];

        require(stream.streamId != 0, "DripCoreCFA: stream not found");
        require(stream.sender == msg.sender, "DripCoreCFA: only sender");
        require(stream.status == StreamStatus.Active || stream.status == StreamStatus.Paused, "DripCoreCFA: stream immutable");
        require(_isRecipientInStream[streamId][recipient], "DripCoreCFA: recipient missing");
        _requireRateUnlocked(stream);

        _syncAccounting(streamId);

        uint256 periodSeconds = stream.endTime > stream.startTime ? (stream.endTime - stream.startTime) : 0;
        require(periodSeconds > 0, "DripCoreCFA: invalid period");

        uint256 oldRate = _recipientRates[streamId][recipient];
        uint256 newRate = newAmountPerPeriod / periodSeconds;
        require(newRate > 0, "DripCoreCFA: rate too small");

        _recipientRates[streamId][recipient] = newRate;

        runtime.totalFlowRate = runtime.totalFlowRate - int96(int256(oldRate)) + int96(int256(newRate));

        if (additionalDeposit > 0) {
            require(superToken.transferFrom(msg.sender, address(this), additionalDeposit), "DripCoreCFA: add deposit failed");
            runtime.remainingBudget += additionalDeposit;
            stream.deposit += additionalDeposit;
        }

        if (stream.status == StreamStatus.Active) {
            require(
                cfaForwarder.updateFlow(
                    address(superToken),
                    address(this),
                    recipient,
                    int96(int256(newRate)),
                    ""
                ),
                "DripCoreCFA: flow update failed"
            );
        }

        emit RecipientRateUpdated(streamId, recipient, oldRate, newRate);
    }

    function getStream(uint256 streamId) external view returns (Stream memory stream) {
        stream = _streams[streamId];
        require(stream.streamId != 0, "DripCoreCFA: stream not found");
    }

    function getSenderStreams(address sender) external view returns (uint256[] memory streamIds) {
        return _senderStreams[sender];
    }

    function getRecipientStreams(address recipient) external view returns (uint256[] memory streamIds) {
        return _recipientStreams[recipient];
    }

    function getUserSentStreams(address user) external view returns (Stream[] memory streams) {
        uint256[] memory ids = _senderStreams[user];
        streams = new Stream[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
            streams[i] = _streams[ids[i]];
        }
    }

    function getUserReceivedStreams(address user) external view returns (Stream[] memory streams) {
        uint256[] memory ids = _recipientStreams[user];
        streams = new Stream[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
            streams[i] = _streams[ids[i]];
        }
    }

    function setPlatformFee(uint256 newFeeBps) external onlyOwner {
        require(newFeeBps <= 1000, "DripCoreCFA: fee too high");
        platformFeeBps = newFeeBps;
    }

    function setPlatformFeeRecipient(address newRecipient) external onlyOwner {
        require(newRecipient != address(0), "DripCoreCFA: invalid recipient");
        platformFeeRecipient = newRecipient;
    }

    function setEngagementRewards(address _engagementRewards) external onlyOwner {
        engagementRewards = _engagementRewards;
    }

    function setEngagementRewardsEnabled(bool _enabled) external onlyOwner {
        engagementRewardsEnabled = _enabled;
    }

    function setInviter(address inviter) external {
        if (inviter == address(0) || inviter == msg.sender) {
            return;
        }
        if (userInviter[msg.sender] == address(0)) {
            userInviter[msg.sender] = inviter;
        }
    }

    function claimEngagementReward(
        address,
        uint256,
        bytes calldata
    ) external pure returns (bool) {
        return false;
    }

    function emergencyWithdrawAll(address[] calldata tokens, address payable to) external onlyOwner {
        require(to != address(0), "DripCoreCFA: invalid recipient");
        for (uint256 i = 0; i < tokens.length; i++) {
            address token = tokens[i];
            if (token == address(0)) {
                continue;
            }
            uint256 bal = ISuperToken(token).balanceOf(address(this));
            if (bal > 0) {
                ISuperToken(token).transfer(to, bal);
            }
        }
        if (address(this).balance > 0) {
            (bool ok, ) = to.call{value: address(this).balance}("");
            require(ok, "DripCoreCFA: native transfer failed");
        }
    }

    function getContractBalances(address[] calldata tokens) external view returns (uint256[] memory balances) {
        balances = new uint256[](tokens.length);
        for (uint256 i = 0; i < tokens.length; i++) {
            if (tokens[i] == address(0)) {
                balances[i] = address(this).balance;
            } else {
                balances[i] = ISuperToken(tokens[i]).balanceOf(address(this));
            }
        }
    }

    receive() external payable {}
}

contracts/DripStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts/utils/math/SafeCast.sol";

/**
 * @title DripStaking
 * @notice Staking contract with Superfluid Distribution Pools for real-time reward streaming
 * @dev Uses Superfluid's GDAv1 for proportional reward distribution
 * @dev Interfaces match official @superfluid-finance/ethereum-contracts v1.14.1
 */

/// @dev Superfluid pool configuration struct (matches official PoolConfig)
struct PoolConfig {
    bool transferabilityForUnitsOwner;
    bool distributionFromAnyAddress;
}

/// @dev Minimal ISuperfluidPool interface (matches official signatures)
interface ISuperfluidPool {
    function updateMemberUnits(address memberAddr, uint128 newUnits) external returns (bool);
    function claimAll(address memberAddr) external returns (bool);
    function claimAll() external returns (bool);
    function getUnits(address memberAddr) external view returns (uint128);
    function getTotalUnits() external view returns (uint128);
    function getTotalFlowRate() external view returns (int96);
    function getMemberFlowRate(address memberAddr) external view returns (int96);
    function getClaimableNow(address memberAddr) external view returns (int256 claimableBalance, uint256 timestamp);
    function getTotalAmountReceivedByMember(address memberAddr) external view returns (uint256);
}

/// @dev Minimal ISuperToken interface (ERC20 + SuperToken basics)
interface ISuperToken {
    function balanceOf(address account) external view returns (uint256);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function upgrade(uint256 amount) external;
    function downgrade(uint256 amount) external;
}

/// @dev GDAv1Forwarder interface — same address (0x6DA13Bde224A05a288748d857b9e7DDEffd1dE08) on all chains
interface IGDAv1Forwarder {
    function createPool(address token, address admin, PoolConfig memory config) external returns (bool success, ISuperfluidPool pool);
    function updateMemberUnits(ISuperfluidPool pool, address memberAddress, uint128 newUnits, bytes calldata userData) external returns (bool success);
    function distributeFlow(address token, address from, ISuperfluidPool pool, int96 requestedFlowRate, bytes calldata userData) external returns (bool success);
    function distribute(address token, address from, ISuperfluidPool pool, uint256 requestedAmount, bytes calldata userData) external returns (bool success);
    function connectPool(ISuperfluidPool pool, bytes calldata userData) external returns (bool success);
    function disconnectPool(ISuperfluidPool pool, bytes calldata userData) external returns (bool success);
    function claimAll(ISuperfluidPool pool, address memberAddress, bytes calldata userData) external returns (bool success);
    function isPool(address token, address account) external view returns (bool);
    function isMemberConnected(ISuperfluidPool pool, address member) external view returns (bool);
    function getFlowDistributionFlowRate(address token, address from, ISuperfluidPool to) external view returns (int96);
}

contract DripStaking is
    Initializable,
    OwnableUpgradeable,
    ReentrancyGuardUpgradeable,
    UUPSUpgradeable
{
    using SafeCast for uint256;
    using SafeCast for int256;

    // ============ State Variables ============

    /// @notice Superfluid Super Token used for staking and rewards
    ISuperToken public superToken;

    /// @notice GDAv1Forwarder for Superfluid pool operations
    IGDAv1Forwarder public gdaForwarder;

    /// @notice Superfluid Pool for reward distribution
    ISuperfluidPool public rewardPool;

    /// @notice Total staked amount across all stakers
    uint256 public totalStaked;

    /// @notice Mapping of staker address to staked amount
    mapping(address => uint256) public stakes;

    /// @notice Mapping of staker address to total rewards claimed
    mapping(address => uint256) public rewardsClaimed;

    /// @notice Admin address that can set reward flow rates
    address public rewardAdmin;

    /// @notice Current reward flow rate (tokens per second)
    int96 public rewardFlowRate;

    /// @notice Scaling factor for unit calculations (prevents precision loss)
    /// @dev Ensures flow rate per unit is significantly > 1 wei
    uint128 public scalingFactor;

    /// @notice Emergency withdrawal enabled flag
    bool public emergencyWithdrawalEnabled;

    // ============ Events ============

    event Staked(
        address indexed staker,
        uint256 amount,
        uint256 newTotalStaked,
        uint128 poolUnits
    );

    event Unstaked(
        address indexed staker,
        uint256 amount,
        uint256 newTotalStaked,
        uint128 poolUnits
    );

    event RewardFlowRateUpdated(int96 newFlowRate);

    event RewardsClaimed(
        address indexed staker,
        uint256 amount
    );

    event RewardPoolCreated(address indexed poolAddress);

    event RewardAdminChanged(address indexed newAdmin);

    event ScalingFactorUpdated(uint128 newFactor);

    // ============ Modifiers ============

    modifier onlyRewardAdmin() {
        require(msg.sender == rewardAdmin || msg.sender == owner(), "Not reward admin");
        _;
    }

    modifier validAmount(uint256 amount) {
        require(amount > 0, "Amount must be > 0");
        _;
    }

    // ============ Initialization ============

    function initialize(
        address _superToken,
        address _gdaForwarder,
        address _rewardAdmin,
        uint128 _scalingFactor
    ) public initializer {
        __Ownable_init(msg.sender);
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();

        require(_superToken != address(0), "Invalid super token");
        require(_gdaForwarder != address(0), "Invalid GDA forwarder");
        require(_rewardAdmin != address(0), "Invalid reward admin");
        require(_scalingFactor > 0, "Scaling factor must be > 0");

        superToken = ISuperToken(_superToken);
        gdaForwarder = IGDAv1Forwarder(_gdaForwarder);
        rewardAdmin = _rewardAdmin;
        scalingFactor = _scalingFactor;
        emergencyWithdrawalEnabled = false;
    }

    // ============ Pool Management ============

    /**
     * @notice Create the reward distribution pool
     * @dev Uses SuperToken's native pool API (Superfluid v2)
     * This must be called before any staking can occur
     */
    function createRewardPool() external onlyOwner returns (address poolAddress) {
        require(address(rewardPool) == address(0), "Pool already created");

        // Create pool via GDAv1Forwarder with address(this) as admin
        // Units not transferable, distribution from any address allowed
        (bool success, ISuperfluidPool pool) = gdaForwarder.createPool(
            address(superToken),
            address(this),
            PoolConfig({
                transferabilityForUnitsOwner: false,
                distributionFromAnyAddress: true
            })
        );
        require(success, "Pool creation failed");
        rewardPool = pool;

        emit RewardPoolCreated(address(rewardPool));
        return address(rewardPool);
    }

    // ============ Staking Functions ============

    /**
     * @notice Stake tokens to earn reward stream
     * @param amount Amount of super tokens to stake
     */
    function stake(uint256 amount)
        external
        nonReentrant
        validAmount(amount)
    {
        require(address(rewardPool) != address(0), "Pool not created");

        // Transfer tokens from staker to contract
        require(
            superToken.transferFrom(msg.sender, address(this), amount),
            "Transfer failed"
        );

        // Update stake
        uint256 oldStake = stakes[msg.sender];
        stakes[msg.sender] = oldStake + amount;
        totalStaked = totalStaked + amount;

        // Update pool units using scaling factor
        // units = staked_amount / scaling_factor
        uint128 newUnits = SafeCast.toUint128(stakes[msg.sender] / scalingFactor);
        require(newUnits > 0, "Stake too small for pool units");
        require(
            rewardPool.updateMemberUnits(msg.sender, newUnits),
            "Member update failed"
        );

        // Auto-connect to pool on first stake for real-time reward streaming
        if (oldStake == 0 && !gdaForwarder.isMemberConnected(rewardPool, msg.sender)) {
            gdaForwarder.connectPool(rewardPool, "");
        }

        emit Staked(msg.sender, amount, totalStaked, newUnits);
    }

    /**
     * @notice Unstake tokens and stop earning rewards
     * @param amount Amount of super tokens to unstake
     */
    function unstake(uint256 amount)
        external
        nonReentrant
        validAmount(amount)
    {
        require(stakes[msg.sender] >= amount, "Insufficient stake");

        // Update stake
        stakes[msg.sender] = stakes[msg.sender] - amount;
        totalStaked = totalStaked - amount;

        // Update pool units
        uint128 newUnits = SafeCast.toUint128(stakes[msg.sender] / scalingFactor);
        require(
            rewardPool.updateMemberUnits(msg.sender, newUnits),
            "Member update failed"
        );

        // Transfer tokens back to staker
        require(superToken.transfer(msg.sender, amount), "Transfer failed");

        emit Unstaked(msg.sender, amount, totalStaked, newUnits);
    }

    // ============ Pool Connection ============

    /**
     * @notice Connect to the reward pool to receive distributions in real-time
     * @dev Automatically claims accumulated rewards and starts streaming to balance
     */
    function connectToPool() external nonReentrant {
        require(address(rewardPool) != address(0), "Pool not created");
        require(stakes[msg.sender] > 0, "No active stake");
        require(!gdaForwarder.isMemberConnected(rewardPool, msg.sender), "Already connected");

        require(gdaForwarder.connectPool(rewardPool, ""), "Connection failed");
    }

    /**
     * @notice Disconnect from the reward pool to stop receiving distributions in real-time
     * @dev Rewards will accumulate in claimable state after disconnecting
     */
    function disconnectFromPool() external nonReentrant {
        require(address(rewardPool) != address(0), "Pool not created");
        require(gdaForwarder.isMemberConnected(rewardPool, msg.sender), "Not connected");

        require(gdaForwarder.disconnectPool(rewardPool, ""), "Disconnection failed");
    }

    /**
     * @notice Check if an address is connected to the reward pool
     * @param member Address to check
     * @return connected True if connected, false otherwise
     */
    function isConnectedToPool(address member) external view returns (bool connected) {
        if (address(rewardPool) == address(0)) {
            return false;
        }
        return gdaForwarder.isMemberConnected(rewardPool, member);
    }

    // ============ Reward Management ============

    /**
     * @notice Set the reward flow rate (tokens per second to distribute)
     * @param newFlowRate Flow rate in tokens/second (with 18 decimals)
     * @dev Flow rate calculation: for 100 tokens/day = 100 / 86400 = ~1157407407407 (wei/second)
     * @dev This actually starts the distribution of rewards into the pool
     */
    function setRewardFlowRate(int96 newFlowRate)
        external
        onlyRewardAdmin
    {
        require(address(rewardPool) != address(0), "Pool not created");
        require(newFlowRate >= 0, "Flow rate must be non-negative");

        // Use GDAv1Forwarder to distribute flow
        require(
            gdaForwarder.distributeFlow(address(superToken), address(this), rewardPool, newFlowRate, ""),
            "distributeFlow failed"
        );

        rewardFlowRate = newFlowRate;
        emit RewardFlowRateUpdated(newFlowRate);
    }

    /**
     * @notice Claim accumulated rewards from the distribution pool
     * @return claimed Amount of tokens claimed
     */
    function claimRewards() public nonReentrant returns (uint256 claimed) {
        require(address(rewardPool) != address(0), "Pool not created");
        require(stakes[msg.sender] > 0, "No active stake");

        // Get balance before claim to calculate amount
        uint256 balBefore = superToken.balanceOf(msg.sender);
        rewardPool.claimAll(msg.sender);
        uint256 balAfter = superToken.balanceOf(msg.sender);
        claimed = balAfter > balBefore ? balAfter - balBefore : 0;

        rewardsClaimed[msg.sender] = rewardsClaimed[msg.sender] + claimed;

        emit RewardsClaimed(msg.sender, claimed);
        return claimed;
    }

    /**
     * @notice Get current reward rate for a staker
     * @param staker Address of the staker
     * @return rate Rate per second (tokens/second) based on proportion of pool
     */
    function getStakerRewardRate(address staker)
        external
        view
        returns (int96 rate)
    {
        if (totalStaked == 0 || stakes[staker] == 0) {
            return 0;
        }

        // Proportion of pool: staker_stake / total_staked
        // Reward rate: (staker_proportion) * rewardFlowRate
        rate = int96(int256((uint256(uint96(rewardFlowRate)) * stakes[staker]) / totalStaked));
        return rate;
    }

    /**
     * @notice Get stake information for an address
     * @param staker Address to query
     * @return staked Amount staked
     * @return claimed Rewards claimed
     * @return rate Current reward rate per second
     */
    function getStakeInfo(address staker)
        external
        view
        returns (
            uint256 staked,
            uint256 claimed,
            int96 rate
        )
    {
        staked = stakes[staker];
        claimed = rewardsClaimed[staker];
        if (totalStaked == 0 || staked == 0) {
            rate = 0;
        } else {
            rate = int96(int256((uint256(uint96(rewardFlowRate)) * staked) / totalStaked));
        }
    }

    /**
     * @notice Get current pool units for a staker
     * @param staker Address to query
     * @return units Current pool units (0 if not a pool member)
     */
    function getPoolUnits(address staker)
        external
        view
        returns (uint128 units)
    {
        if (address(rewardPool) == address(0)) {
            return 0;
        }
        return rewardPool.getUnits(staker);
    }

    // ============ Admin Functions ============

    /**
     * @notice Update reward admin address
     * @param newAdmin New admin address
     */
    function setRewardAdmin(address newAdmin) external onlyOwner {
        require(newAdmin != address(0), "Invalid address");
        rewardAdmin = newAdmin;
        emit RewardAdminChanged(newAdmin);
    }

    /**
     * @notice Update scaling factor for unit calculations
     * @param newFactor New scaling factor (must be > 0)
     * @dev Recommended value: 1e15 to 1e18 depending on expected stake sizes
     */
    function setScalingFactor(uint128 newFactor) external onlyOwner {
        require(newFactor > 0, "Scaling factor must be > 0");
        scalingFactor = newFactor;
        emit ScalingFactorUpdated(newFactor);
    }

    /**
     * @notice Enable emergency withdrawal (withdraws without claiming rewards)
     */
    function enableEmergencyWithdrawal() external onlyOwner {
        emergencyWithdrawalEnabled = true;
    }

    /**
     * @notice Disable emergency withdrawal
     */
    function disableEmergencyWithdrawal() external onlyOwner {
        emergencyWithdrawalEnabled = false;
    }

    /**
     * @notice Emergency unstake if pool is compromised
     */
    function emergencyUnstake() external nonReentrant {
        require(emergencyWithdrawalEnabled, "Emergency withdrawal disabled");
        require(stakes[msg.sender] > 0, "No stake");

        uint256 amount = stakes[msg.sender];
        stakes[msg.sender] = 0;
        totalStaked = totalStaked - amount;

        require(rewardPool.updateMemberUnits(msg.sender, 0), "Member update failed");
        require(superToken.transfer(msg.sender, amount), "Transfer failed");

        emit Unstaked(msg.sender, amount, totalStaked, 0);
    }

    /**
     * @notice Recover adjustment flow dust (rounding remainder sent to pool admin)
     * @param to Address to send recovered tokens to
     */
    function recoverAdjustmentFlow(address to) external onlyOwner {
        require(to != address(0), "Invalid address");
        uint256 contractBalance = superToken.balanceOf(address(this));
        uint256 excess = contractBalance > totalStaked ? contractBalance - totalStaked : 0;
        require(excess > 0, "No excess to recover");
        require(superToken.transfer(to, excess), "Transfer failed");
    }

    /**
     * @notice Get claimable rewards for a staker
     * @param staker Address to query
     * @return claimable Amount of tokens claimable now
     */
    function getClaimableRewards(address staker) external view returns (int256 claimable) {
        if (address(rewardPool) == address(0) || stakes[staker] == 0) {
            return 0;
        }
        (claimable, ) = rewardPool.getClaimableNow(staker);
    }

    // ============ Upgrade Authorization ============

    function _authorizeUpgrade(address newImplementation)
        internal
        override
        onlyOwner
    {}

    // ============ Receive Function ============

    receive() external payable {}
}

contracts/interfaces/IDrip.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title IDrip
 * @notice Interface for the Drip payment streaming contract
 * @dev Defines the core functionality for creating and managing payment streams
 */
interface IDrip {
    /// @notice Stream status enumeration
    enum StreamStatus {
        Pending,    // Stream created but not started
        Active,     // Stream is active and accruing
        Paused,     // Stream is paused
        Cancelled,  // Stream was cancelled
        Completed   // Stream completed naturally
    }

    /// @notice Stream structure
    struct Stream {
        uint256 streamId;           // Unique identifier for the stream
        address sender;             // Address that created the stream
        address[] recipients;       // Addresses receiving the stream (multiple recipients)
        address token;              // ERC20 token address (address(0) for native CELO)
        uint256 deposit;            // Total amount deposited (remaining is derived)
        uint256 startTime;          // Timestamp when stream starts
        uint256 endTime;            // Timestamp when stream ends (calculated from duration)
        StreamStatus status;         // Current status of the stream
        uint256 rateLockUntil;      // Timestamp until which rate modifications are locked
        string title;               // Optional title (max 120 chars)
        string description;         // Optional description (max 1024 chars)
    }

    /// @notice Recipient information structure
    struct RecipientInfo {
        address recipient;          // Recipient address
        uint256 ratePerSecond;      // Rate per second for this recipient
        uint256 totalWithdrawn;      // Total amount withdrawn by this recipient
        uint256 lastWithdrawTime;   // Last withdrawal timestamp
        uint256 currentAccrued;     // Current accrued amount (not yet withdrawn)
    }

    /// @notice Emitted when a new stream is created
    event StreamCreated(
        uint256 indexed streamId,
        address indexed sender,
        address[] recipients,
        address token,
        uint256 deposit,
        uint256 startTime,
        uint256 endTime,
        string title,
        string description
    );

    /// @notice Emitted when a stream is paused
    event StreamPaused(uint256 indexed streamId, address indexed by);

    /// @notice Emitted when a stream is resumed
    event StreamResumed(uint256 indexed streamId, address indexed by);

    /// @notice Emitted when a stream is cancelled
    event StreamCancelled(
        uint256 indexed streamId,
        address indexed by,
        uint256 refundAmount
    );

    /// @notice Emitted when funds are withdrawn from a stream
    event StreamWithdrawn(
        uint256 indexed streamId,
        address indexed recipient,
        uint256 amount
    );

    /// @notice Emitted when a stream completes naturally
    event StreamCompleted(uint256 indexed streamId);

    /// @notice Emitted when a stream's rate is locked
    event StreamRateLocked(uint256 indexed streamId, uint256 lockUntil);

    /// @notice Emitted when a stream receives additional deposit or extended duration
    event StreamExtended(uint256 indexed streamId, uint256 newEndTime, uint256 addedDeposit);

    /// @notice Emitted when a recipient is added to a stream
    event RecipientAdded(
        uint256 indexed streamId,
        address indexed recipient,
        uint256 amountPerPeriod,
        uint256 ratePerSecond
    );

    /// @notice Emitted when a recipient is removed from a stream
    event RecipientRemoved(
        uint256 indexed streamId,
        address indexed recipient,
        uint256 refundAmount
    );

    /// @notice Emitted when emergency withdrawal is performed
    event EmergencyWithdrawal(
        address indexed token,
        address indexed to,
        uint256 amount
    );

    /**
     * @notice Emergency withdrawal function - withdraw ALL funds from contract (owner only)
     * @param tokens Array of ERC20 token addresses to withdraw (can be empty if only withdrawing native)
     * @param to Address to send all funds to
     */
    function emergencyWithdrawAll(address[] calldata tokens, address payable to) external;

    /**
     * @notice Get contract balances for multiple tokens (view function)
     * @param tokens Array of token addresses to check (use address(0) for native CELO)
     * @return balances Array of balances corresponding to the tokens array
     */
    function getContractBalances(address[] calldata tokens) external view returns (uint256[] memory balances);

    /// @notice Emitted when a recipient's rate is updated
    event RecipientRateUpdated(
        uint256 indexed streamId,
        address indexed recipient,
        uint256 oldRatePerSecond,
        uint256 newRatePerSecond
    );

    /**
     * @notice Create a new payment stream with multiple recipients
     * @param recipients Array of addresses that will receive the streamed payments
     * @param token ERC20 token address (address(0) for native CELO)
     * @param amountsPerPeriod Array of amounts per period for each recipient (parallel to recipients)
     * @param periodSeconds Duration of the period in seconds (e.g., 30 days)
     * @param deposit Total amount to deposit (must cover all recipients)
     * @param title Optional title for the stream (max 120 chars)
     * @param description Optional description (max 1024 chars)
     * @return streamId Unique identifier for the created stream
     */
    function createStream(
        address[] calldata recipients,
        address token,
        uint256[] calldata amountsPerPeriod,
        uint256 periodSeconds,
        uint256 deposit,
        string calldata title,
        string calldata description
    ) external payable returns (uint256 streamId);

    /**
     * @notice Get the current balance available for withdrawal for a specific recipient
     * @param streamId The stream identifier
     * @param recipient The recipient address
     * @return balance The amount available for withdrawal
     */
    function getRecipientBalance(uint256 streamId, address recipient) external view returns (uint256 balance);

    /**
     * @notice Withdraw available balance from a stream (for a specific recipient)
     * @param streamId The stream identifier
     * @param recipient The recipient address withdrawing
     * @return withdrawn The amount actually withdrawn (always the full available balance)
     */
    function withdrawFromStream(uint256 streamId, address recipient) external returns (uint256 withdrawn);

    /**
     * @notice Get detailed information about a specific recipient in a stream
     * @param streamId The stream identifier
     * @param recipient The recipient address
     * @return info Recipient information structure
     */
    function getRecipientInfo(uint256 streamId, address recipient) external view returns (RecipientInfo memory info);

    /**
     * @notice Get information about all recipients in a stream
     * @param streamId The stream identifier
     * @return recipients Array of recipient information
     */
    function getAllRecipientsInfo(uint256 streamId) external view returns (RecipientInfo[] memory recipients);

    /**
     * @notice Pause an active stream
     * @param streamId The stream identifier
     */
    function pauseStream(uint256 streamId) external;

    /**
     * @notice Resume a paused stream
     * @param streamId The stream identifier
     */
    function resumeStream(uint256 streamId) external;

    /**
     * @notice Cancel a stream and refund remaining balance
     * @param streamId The stream identifier
     */
    function cancelStream(uint256 streamId) external;

    /**
     * @notice Lock rate-related modifications for a stream
     * @param streamId The stream identifier
     * @param lockDuration Duration (in seconds) to lock rate changes
     */
    function lockStreamRate(uint256 streamId, uint256 lockDuration) external;

    /**
     * @notice Extend a stream's duration and/or add additional deposit
     * @param streamId The stream identifier
     * @param newEndTime The new end time (0 to keep current end time)
     * @param depositAmount Total additional deposit to add (before fees)
     */
    function extendStream(
        uint256 streamId,
        uint256 newEndTime,
        uint256 depositAmount
    ) external payable;

    /**
     * @notice Add a new recipient to an existing stream
     * @param streamId The stream identifier
     * @param recipient The new recipient address
     * @param amountPerPeriod The amount per period for the new recipient
     * @param additionalDeposit Additional deposit required to cover the new recipient
     */
    function addRecipient(
        uint256 streamId,
        address recipient,
        uint256 amountPerPeriod,
        uint256 additionalDeposit
    ) external payable;

    /**
     * @notice Remove a recipient from an existing stream
     * @param streamId The stream identifier
     * @param recipient The recipient address to remove
     * @dev Refunds any unaccrued deposit allocated to this recipient
     */
    function removeRecipient(uint256 streamId, address recipient) external;

    /**
     * @notice Update a recipient's rate in an existing stream
     * @param streamId The stream identifier
     * @param recipient The recipient address
     * @param newAmountPerPeriod The new amount per period
     * @param additionalDeposit Additional deposit if increasing rate, or refund if decreasing
     */
    function updateRecipientRate(
        uint256 streamId,
        address recipient,
        uint256 newAmountPerPeriod,
        uint256 additionalDeposit
    ) external payable;

    /**
     * @notice Get stream details
     * @param streamId The stream identifier
     * @return stream The stream structure
     */
    function getStream(uint256 streamId) external view returns (Stream memory stream);
}

